/* بيانات قاموس المصطلحات — منقولة من ملف «قاموس مصطلحات IR-01 مع النطق الصوتي» (316 مصطلحًا)
   الحقول: t مصطلح، ar معنى، ap نطق تقريبي بالعربية، def/defAr تعريف، ex/exAr مثال، src موضوع الملف الأصلي، lv الأهمية في الملف الأصلي،
   c تصنيف الدراسة (تنظيم مبدئي من المنصة)، l دروس المنصة التي يرد فيها المصطلح (حُسبت من نصوص المنصة نفسها).
   لا توجد في الملف الأصلي مراجع أو أرقام صفحات أو رموز IPA، ولذلك لا تُعرض. */
'use strict';
const VOCAB_CATEGORIES=[{"id": "c01", "ar": "أساسيات الإشعاع والنشاط الإشعاعي", "en": "Radiation & Radioactivity Basics", "extra": false}, {"id": "c02", "ar": "الأشعة السينية وأجهزة توليد الأشعة السينية", "en": "X-rays & X-ray Generators", "extra": false}, {"id": "c03", "ar": "أشعة غاما والمصادر المشعة المختومة", "en": "Gamma Rays & Sealed Sources", "extra": false}, {"id": "c04", "ar": "المصادر عالية النشاط", "en": "High-Activity Sources", "extra": false}, {"id": "c05", "ar": "تفاعلات الإشعاع مع المادة", "en": "Radiation–Matter Interactions", "extra": false}, {"id": "c06", "ar": "الجرعة الإشعاعية ووحدات القياس", "en": "Dose & Units", "extra": false}, {"id": "c07", "ar": "أجهزة الكشف والقياس الإشعاعي", "en": "Detection & Measurement", "extra": false}, {"id": "c08", "ar": "مبادئ الحماية من الإشعاع", "en": "Radiation Protection Principles", "extra": false}, {"id": "c09", "ar": "حدود الجرعات ومراقبة التعرض", "en": "Dose Limits & Exposure Monitoring", "extra": false}, {"id": "c10", "ar": "مناطق العمل واللافتات والتحذيرات", "en": "Work Areas, Signs & Warnings", "extra": false}, {"id": "c11", "ar": "التصوير الإشعاعي الصناعي وإجراءات التشغيل", "en": "Industrial Radiography Operations", "extra": false}, {"id": "c12", "ar": "المسح الإشعاعي ومراقبة المناطق", "en": "Surveys & Area Monitoring", "extra": false}, {"id": "c13", "ar": "الحوادث والطوارئ الإشعاعية", "en": "Incidents & Emergencies", "extra": false}, {"id": "c14", "ar": "المتطلبات التنظيمية والتراخيص والمسؤوليات", "en": "Regulatory Requirements & Licensing", "extra": false}, {"id": "x01", "ar": "الآثار الحيوية للإشعاع", "en": "Biological Effects", "extra": true}, {"id": "x02", "ar": "التلوث الإشعاعي", "en": "Contamination", "extra": true}, {"id": "x03", "ar": "نقل المواد المشعة", "en": "Transport of Radioactive Material", "extra": true}, {"id": "x04", "ar": "جودة الصورة والعيوب", "en": "Image Quality & Defects", "extra": true}];
const VOCAB_TERMS=[{"id":1,"t":"atom","pos":"اسم","ar":"ذرة","ap":"آتـم","def":"The smallest unit of an element.","defAr":"أصغر وحدة من العنصر تحتفظ بخواصه.","ex":"An atom has a nucleus and electrons.","exAr":"للذرة نواة وإلكترونات.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":[]},{"id":2,"t":"nucleus","pos":"اسم","ar":"نواة","ap":"نيوكلياس","def":"The central part of an atom with protons and neutrons.","defAr":"مركز الذرة وفيه البروتونات والنيوترونات.","ex":"The nucleus is positively charged.","exAr":"النواة موجبة الشحنة.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":[]},{"id":3,"t":"nuclei","pos":"اسم","ar":"نوى (جمع نواة)","ap":"نيوكلاي","def":"Plural of nucleus.","defAr":"جمع كلمة nucleus.","ex":"Unstable nuclei emit radiation.","exAr":"النوى غير المستقرة تُصدر إشعاعًا.","src":"بنية الذرة","lv":"مهم","c":"c01","l":[]},{"id":4,"t":"nucleon","pos":"اسم","ar":"نيوكليون (جسيم نووي)","ap":"نيوكليون","def":"A proton or a neutron in the nucleus.","defAr":"اسم يجمع البروتون والنيوترون داخل النواة.","ex":"Protons and neutrons are nucleons.","exAr":"البروتونات والنيوترونات نيوكليونات.","src":"بنية الذرة","lv":"مهم","c":"c01","l":[]},{"id":5,"t":"proton","pos":"اسم","ar":"بروتون","ap":"بروتون","def":"A positive particle in the nucleus.","defAr":"جسيم موجب الشحنة في النواة.","ex":"The proton has a positive charge.","exAr":"للبروتون شحنة موجبة.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":[]},{"id":6,"t":"neutron","pos":"اسم","ar":"نيوترون","ap":"نيوترون","def":"A neutral particle in the nucleus.","defAr":"جسيم متعادل الشحنة في النواة.","ex":"A neutron has no electric charge.","exAr":"النيوترون بلا شحنة كهربائية.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":[]},{"id":7,"t":"electron","pos":"اسم","ar":"إلكترون","ap":"إلكترون","def":"A small negative particle around the nucleus.","defAr":"جسيم سالب صغير يدور حول النواة.","ex":"The electron has the smallest mass.","exAr":"للإلكترون أصغر كتلة.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":["tcs85:tcs-10"]},{"id":8,"t":"atomic number","pos":"عبارة اصطلاحية","ar":"العدد الذري (Z)","ap":"أتومِك نامبر","def":"The number of protons in an atom.","defAr":"عدد البروتونات في الذرة، ويحدد العنصر.","ex":"Cobalt has atomic number 27.","exAr":"العدد الذري للكوبالت 27.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":[]},{"id":9,"t":"mass number","pos":"عبارة اصطلاحية","ar":"العدد الكتلي (A)","ap":"ماس نامبر","def":"The total number of protons and neutrons.","defAr":"مجموع البروتونات والنيوترونات.","ex":"Co-60 has mass number 60.","exAr":"العدد الكتلي لـ Co-60 هو 60.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":[]},{"id":10,"t":"isotope","pos":"اسم","ar":"نظير","ap":"آيسوتوب","def":"Atoms of one element with different neutron numbers.","defAr":"ذرات للعنصر نفسه تختلف في عدد النيوترونات.","ex":"Ir-192 is an isotope of iridium.","exAr":"Ir-192 نظير للإيريديوم.","src":"بنية الذرة","lv":"أساسي","c":"c01","l":[]},{"id":11,"t":"isotone","pos":"اسم","ar":"نظير نيوتروني (متساوي النيوترونات)","ap":"آيسوتون","def":"Atoms of different elements with equal neutron number.","defAr":"ذرات لعناصر مختلفة لها العدد نفسه من النيوترونات.","ex":"Isotones have equal N but different Z.","exAr":"لها N متساوٍ وZ مختلف.","src":"بنية الذرة","lv":"إضافي","c":"c01","l":[]},{"id":12,"t":"isobar","pos":"اسم","ar":"نظير كتلي (متساوي العدد الكتلي)","ap":"آيسوبار","def":"Atoms with the same mass number but different atomic numbers.","defAr":"ذرات لها العدد الكتلي نفسه وعدد ذري مختلف.","ex":"Isobars have equal A.","exAr":"المتساويات الكتلية لها A متساوٍ.","src":"بنية الذرة","lv":"إضافي","c":"c01","l":[]},{"id":13,"t":"nuclide","pos":"اسم","ar":"نويدة","ap":"نيوكلايد","def":"A type of atom defined by protons and neutrons.","defAr":"نوع من الذرات يحدده عدد بروتوناته ونيوتروناته.","ex":"Each nuclide has its own half-life.","exAr":"لكل نويدة نصف عمر خاص بها.","src":"بنية الذرة","lv":"مهم","c":"c01","l":[]},{"id":14,"t":"radionuclide","pos":"اسم","ar":"نويدة مشعة","ap":"ريديو نيوكلايد","def":"An unstable nuclide that emits radiation.","defAr":"نويدة غير مستقرة تُصدر إشعاعًا.","ex":"Cs-137 is a radionuclide.","exAr":"Cs-137 نويدة مشعة.","src":"النشاط الإشعاعي","lv":"أساسي","c":"c01","l":[]},{"id":15,"t":"radioisotope","pos":"اسم","ar":"نظير مشع","ap":"ريديو آيسوتوب","def":"A radioactive isotope of an element.","defAr":"نظير مشع لعنصر ما.","ex":"Iridium-192 is a radioisotope.","exAr":"إيريديوم-192 نظير مشع.","src":"النشاط الإشعاعي","lv":"أساسي","c":"c01","l":[]},{"id":16,"t":"ion","pos":"اسم","ar":"أيون","ap":"آيون","def":"An atom with an electric charge.","defAr":"ذرة أو جزيء مشحون كهربائيًا.","ex":"Radiation can create ion pairs.","exAr":"الإشعاع قد يُنتج أزواجًا أيونية.","src":"التأين","lv":"مهم","c":"c01","l":[]},{"id":17,"t":"ion pair","pos":"عبارة اصطلاحية","ar":"زوج أيوني","ap":"آيون بير","def":"An ion and the free electron removed from an atom.","defAr":"أيون موجب وإلكترون حر ناتجان عن التأين.","ex":"Gas detectors collect ion pairs.","exAr":"كواشف الغاز تجمع الأزواج الأيونية.","src":"التأين","lv":"مهم","c":"c01","l":[]},{"id":18,"t":"ionization","pos":"اسم","ar":"تأين","ap":"آيونايزيشن","def":"Removing an electron from an atom.","defAr":"نزع إلكترون من الذرة.","ex":"Ionization damages living cells.","exAr":"التأين يضر بالخلايا الحية.","src":"التأين","lv":"أساسي","c":"c01","l":["tcs85:tcs-2"]},{"id":19,"t":"ionizing radiation","pos":"عبارة اصطلاحية","ar":"إشعاع مؤيّن","ap":"آيونايزنغ ريديايشن","def":"Radiation with enough energy to ionize atoms.","defAr":"إشعاع لديه طاقة كافية لتأيين الذرات.","ex":"Gamma rays are ionizing radiation.","exAr":"أشعة غاما إشعاع مؤيّن.","src":"أنواع الإشعاع","lv":"أساسي","c":"c01","l":["tcs85:tcs-2"]},{"id":20,"t":"excitation","pos":"اسم","ar":"إثارة","ap":"إكسايتيشن","def":"Raising an electron to a higher energy level without removing it.","defAr":"رفع إلكترون لمستوى طاقة أعلى دون نزعه.","ex":"Excitation is not ionization.","exAr":"الإثارة ليست تأينًا.","src":"التأين","lv":"مهم","c":"c01","l":[]},{"id":21,"t":"radiation","pos":"اسم","ar":"إشعاع","ap":"ريديايشن","def":"Energy traveling as waves or particles.","defAr":"طاقة تنتقل على شكل موجات أو جسيمات.","ex":"Radiation is emitted by the source.","exAr":"الإشعاع يصدر من المصدر.","src":"أنواع الإشعاع","lv":"أساسي","c":"c01","l":["tcs85:tcs-2","tcs85:tcs-5","tcs85:tcs-10"]},{"id":22,"t":"radioactivity","pos":"اسم","ar":"نشاط إشعاعي (ظاهرة)","ap":"ريديو أكتيفيتي","def":"The spontaneous decay of unstable nuclei.","defAr":"التحلل التلقائي للنوى غير المستقرة.","ex":"Radioactivity is measured in becquerel.","exAr":"يُقاس النشاط الإشعاعي بالبيكريل.","src":"النشاط الإشعاعي","lv":"أساسي","c":"c01","l":[]},{"id":23,"t":"radioactive","pos":"صفة","ar":"مشع","ap":"ريديو أكتف","def":"Able to emit ionizing radiation.","defAr":"قادر على إصدار إشعاع مؤيّن.","ex":"Handle radioactive material carefully.","exAr":"تعامل بحذر مع المواد المشعة.","src":"النشاط الإشعاعي","lv":"أساسي","c":"c01","l":["tcs85:tcs-2","tcs85:tcs-9","nrrc:nrrc-1"]},{"id":24,"t":"activity","pos":"اسم","ar":"نشاط (إشعاعي)","ap":"أكتيفيتي","def":"The number of nuclear decays per second.","defAr":"عدد التحللات النووية في الثانية.","ex":"The activity of the source is 3.7 TBq.","exAr":"نشاط المصدر 3.7 تيرابيكريل.","src":"النشاط الإشعاعي","lv":"أساسي","c":"c01","l":[]},{"id":25,"t":"specific activity","pos":"عبارة اصطلاحية","ar":"النشاط النوعي","ap":"سبيسيفك أكتيفيتي","def":"Activity per unit mass.","defAr":"النشاط لكل وحدة كتلة.","ex":"Specific activity is measured in Bq/g.","exAr":"النشاط النوعي يُقاس بـ Bq/g.","src":"النشاط الإشعاعي","lv":"مهم","c":"c01","l":[]},{"id":26,"t":"decay","pos":"اسم / فعل","ar":"تحلل / اضمحلال","ap":"ديكاي","def":"Spontaneous change of an unstable nucleus.","defAr":"تغير تلقائي لنواة غير مستقرة.","ex":"The source decays over time.","exAr":"يتحلل المصدر مع الزمن.","src":"النشاط الإشعاعي","lv":"أساسي","c":"c01","l":[]},{"id":27,"t":"disintegration","pos":"اسم","ar":"تفكك (نووي)","ap":"ديسنتغريشن","def":"One nuclear decay event.","defAr":"حدث تحلل نووي واحد.","ex":"One disintegration per second equals 1 Bq.","exAr":"تفكك واحد في الثانية يساوي 1 Bq.","src":"النشاط الإشعاعي","lv":"مهم","c":"c01","l":[]},{"id":28,"t":"decay constant","pos":"عبارة اصطلاحية","ar":"ثابت التحلل (λ)","ap":"ديكاي كونستانت","def":"The probability of decay per unit time.","defAr":"احتمال التحلل لكل وحدة زمن.","ex":"The decay constant is lambda.","exAr":"ثابت التحلل هو لامدا.","src":"النشاط الإشعاعي","lv":"مهم","c":"c01","l":[]},{"id":29,"t":"half-life","pos":"اسم","ar":"عمر النصف","ap":"هاف لايف","def":"Time for activity to fall to half.","defAr":"الزمن اللازم ليقل النشاط إلى النصف.","ex":"The half-life of Co-60 is 5.27 years.","exAr":"عمر النصف لـ Co-60 هو 5.27 سنة.","src":"النشاط الإشعاعي","lv":"أساسي","c":"c01","l":[]},{"id":30,"t":"parent","pos":"اسم","ar":"نواة أم","ap":"بيرنت","def":"The original radionuclide in a decay chain.","defAr":"النويدة الأصلية التي تتحلل.","ex":"The parent decays into a daughter.","exAr":"النواة الأم تتحلل إلى نواة ابنة.","src":"النشاط الإشعاعي","lv":"إضافي","c":"c01","l":[]},{"id":31,"t":"daughter","pos":"اسم","ar":"نواة ابنة","ap":"دوتر","def":"The nuclide produced by decay.","defAr":"النويدة الناتجة عن التحلل.","ex":"The daughter may also be radioactive.","exAr":"قد تكون النواة الابنة مشعة أيضًا.","src":"النشاط الإشعاعي","lv":"إضافي","c":"c01","l":[]},{"id":32,"t":"secular equilibrium","pos":"عبارة اصطلاحية","ar":"اتزان دائم","ap":"سيكيولر إكويلبريوم","def":"Equilibrium when the parent is much longer-lived than the daughter.","defAr":"اتزان عندما يكون عمر الأم أطول بكثير من الابنة.","ex":"Secular equilibrium needs a very long parent half-life.","exAr":"الاتزان الدائم يتطلب نصف عمر طويلًا جدًا للأم.","src":"النشاط الإشعاعي","lv":"إضافي","c":"c01","l":[]},{"id":33,"t":"transient equilibrium","pos":"عبارة اصطلاحية","ar":"اتزان انتقالي","ap":"ترانزينت إكويلبريوم","def":"Equilibrium when the parent is longer-lived but not by much.","defAr":"اتزان عندما تكون الأم أطول عمرًا لكن ليس بكثير.","ex":"Transient equilibrium differs from secular.","exAr":"الاتزان الانتقالي يختلف عن الدائم.","src":"النشاط الإشعاعي","lv":"إضافي","c":"c01","l":[]},{"id":34,"t":"alpha particle","pos":"عبارة اصطلاحية","ar":"جسيم ألفا","ap":"ألفا بارتيكل","def":"A helium nucleus with 2 protons and 2 neutrons.","defAr":"نواة هيليوم من بروتونين ونيوترونين.","ex":"Paper can stop alpha particles.","exAr":"الورقة توقف جسيمات ألفا.","src":"أنواع الإشعاع","lv":"أساسي","c":"c01","l":[]},{"id":35,"t":"beta particle","pos":"عبارة اصطلاحية","ar":"جسيم بيتا","ap":"بيتا بارتيكل","def":"A fast electron or positron from the nucleus.","defAr":"إلكترون أو بوزيترون سريع من النواة.","ex":"Beta particles are stopped by plastic.","exAr":"يوقف البلاستيك جسيمات بيتا.","src":"أنواع الإشعاع","lv":"أساسي","c":"c01","l":[]},{"id":36,"t":"gamma ray","pos":"عبارة اصطلاحية","ar":"أشعة غاما","ap":"غاما راي","def":"High-energy electromagnetic radiation from the nucleus.","defAr":"إشعاع كهرومغناطيسي عالي الطاقة من النواة.","ex":"Gamma rays are very penetrating.","exAr":"أشعة غاما شديدة النفاذ.","src":"أنواع الإشعاع","lv":"أساسي","c":"c01","l":[]},{"id":37,"t":"x-ray","pos":"اسم","ar":"أشعة سينية (أشعة إكس)","ap":"إكس راي","def":"Electromagnetic radiation made by electrons hitting a target.","defAr":"إشعاع كهرومغناطيسي ينتج من اصطدام إلكترونات بهدف.","ex":"An X-ray tube needs high voltage.","exAr":"أنبوب الأشعة السينية يحتاج جهدًا عاليًا.","src":"أنواع الإشعاع","lv":"أساسي","c":"c01","l":[]},{"id":38,"t":"photon","pos":"اسم","ar":"فوتون","ap":"فوتون","def":"A packet of electromagnetic energy.","defAr":"حزمة من الطاقة الكهرومغناطيسية.","ex":"A photon has no mass.","exAr":"الفوتون لا كتلة له.","src":"أنواع الإشعاع","lv":"أساسي","c":"c01","l":[]},{"id":39,"t":"positron","pos":"اسم","ar":"بوزيترون","ap":"بوزيترون","def":"The positive antiparticle of the electron.","defAr":"الجسيم المضاد للإلكترون وشحنته موجبة.","ex":"A positron is emitted in beta-plus decay.","exAr":"يصدر البوزيترون في تحلل بيتا الموجب.","src":"أنواع الإشعاع","lv":"إضافي","c":"c01","l":[]},{"id":40,"t":"neutrino","pos":"اسم","ar":"نيوترينو","ap":"نيوترينو","def":"A tiny neutral particle emitted in beta decay.","defAr":"جسيم صغير متعادل يصدر مع تحلل بيتا.","ex":"A neutrino rarely interacts with matter.","exAr":"النيوترينو نادرًا ما يتفاعل مع المادة.","src":"أنواع الإشعاع","lv":"إضافي","c":"c01","l":[]},{"id":41,"t":"electromagnetic","pos":"صفة","ar":"كهرومغناطيسي","ap":"إليكترو ماغنتِك","def":"Related to electric and magnetic fields.","defAr":"متعلق بالمجالين الكهربائي والمغناطيسي.","ex":"X-rays are electromagnetic radiation.","exAr":"الأشعة السينية إشعاع كهرومغناطيسي.","src":"أنواع الإشعاع","lv":"مهم","c":"c01","l":[]},{"id":42,"t":"wavelength","pos":"اسم","ar":"طول موجي","ap":"ويف لِنغث","def":"Distance between two wave peaks.","defAr":"المسافة بين قمتين متتاليتين للموجة.","ex":"Short wavelength means high energy.","exAr":"الطول الموجي القصير يعني طاقة عالية.","src":"أنواع الإشعاع","lv":"إضافي","c":"c01","l":[]},{"id":43,"t":"penetrating","pos":"صفة","ar":"نافذ (شديد الاختراق)","ap":"بنيتريتنغ","def":"Able to pass through matter.","defAr":"قادر على اختراق المادة.","ex":"Gamma rays are penetrating.","exAr":"أشعة غاما نافذة.","src":"أنواع الإشعاع","lv":"مهم","c":"c01","l":[]},{"id":44,"t":"energy","pos":"اسم","ar":"طاقة","ap":"إنرجي","def":"The ability to do work.","defAr":"القدرة على بذل شغل.","ex":"Higher energy gives more penetration.","exAr":"الطاقة الأعلى تعني نفاذية أكبر.","src":"الفيزياء","lv":"أساسي","c":"c01","l":[]},{"id":45,"t":"electron volt","pos":"عبارة اصطلاحية","ar":"إلكترون فولت (eV)","ap":"إلكترون فولت","def":"A small unit of energy for particles.","defAr":"وحدة صغيرة لطاقة الجسيمات.","ex":"Gamma energy is given in keV or MeV.","exAr":"تُعطى طاقة غاما بـ keV أو MeV.","src":"الفيزياء","lv":"أساسي","c":"c01","l":[]},{"id":46,"t":"interaction","pos":"اسم","ar":"تفاعل","ap":"إنتراكشن","def":"How radiation acts with matter.","defAr":"كيفية تأثير الإشعاع في المادة.","ex":"Photoelectric effect is an interaction.","exAr":"الأثر الكهروضوئي نوع من التفاعل.","src":"التفاعل مع المادة","lv":"أساسي","c":"c05","l":[]},{"id":47,"t":"photoelectric effect","pos":"عبارة اصطلاحية","ar":"الأثر الكهروضوئي","ap":"فوتوإلكتريك إفكت","def":"A photon gives all its energy to an electron.","defAr":"فوتون يعطي كل طاقته لإلكترون ويختفي.","ex":"Photoelectric effect is strong in lead.","exAr":"الأثر الكهروضوئي قوي في الرصاص.","src":"التفاعل مع المادة","lv":"أساسي","c":"c05","l":[]},{"id":48,"t":"compton scattering","pos":"عبارة اصطلاحية","ar":"استطارة كومبتون","ap":"كومبتون سكاترنغ","def":"A photon loses part of its energy to an electron and changes direction.","defAr":"فوتون يفقد جزءًا من طاقته لإلكترون ويغير اتجاهه.","ex":"Compton scattering dominates at medium energies.","exAr":"تسود استطارة كومبتون عند الطاقات المتوسطة.","src":"التفاعل مع المادة","lv":"أساسي","c":"c05","l":[]},{"id":49,"t":"pair production","pos":"عبارة اصطلاحية","ar":"إنتاج الزوج","ap":"بير برودكشن","def":"A photon becomes an electron and a positron.","defAr":"فوتون عالي الطاقة يتحول إلى إلكترون وبوزيترون.","ex":"Pair production needs more than 1.022 MeV.","exAr":"إنتاج الزوج يحتاج أكثر من 1.022 MeV.","src":"التفاعل مع المادة","lv":"أساسي","c":"c05","l":[]},{"id":50,"t":"annihilation","pos":"اسم","ar":"فناء (إفناء)","ap":"أنايليشن","def":"A positron and electron destroy each other and make photons.","defAr":"التقاء بوزيترون وإلكترون وتحولهما إلى فوتونات.","ex":"Annihilation produces two photons.","exAr":"الفناء ينتج فوتونين.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":51,"t":"scattering","pos":"اسم","ar":"استطارة (تشتت)","ap":"سكاترنغ","def":"Change in direction of radiation after interaction.","defAr":"تغير اتجاه الإشعاع بعد التفاعل.","ex":"Scattering can raise dose near the area.","exAr":"الاستطارة قد ترفع الجرعة قرب المنطقة.","src":"التفاعل مع المادة","lv":"أساسي","c":"c05","l":[]},{"id":52,"t":"rayleigh scattering","pos":"عبارة اصطلاحية","ar":"استطارة رايلي","ap":"ريلي سكاترنغ","def":"Elastic scattering of low-energy photons.","defAr":"استطارة مرنة لفوتونات منخفضة الطاقة.","ex":"Rayleigh scattering has no energy loss.","exAr":"لا فقد للطاقة في استطارة رايلي.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":53,"t":"elastic","pos":"صفة","ar":"مرن","ap":"إلاستِك","def":"Without loss of energy in a collision.","defAr":"دون فقدان طاقة في التصادم.","ex":"Elastic scattering conserves energy.","exAr":"الاستطارة المرنة تحفظ الطاقة.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":54,"t":"inelastic","pos":"صفة","ar":"غير مرن","ap":"إن إلاستِك","def":"With loss of energy in a collision.","defAr":"مع فقدان جزء من الطاقة في التصادم.","ex":"Neutrons can have inelastic scattering.","exAr":"قد يحدث للنيوترونات استطارة غير مرنة.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":55,"t":"bremsstrahlung","pos":"اسم","ar":"إشعاع الكبح (برمستراهلونغ)","ap":"برِمشترالونغ","def":"X-rays made when electrons slow down near a nucleus.","defAr":"أشعة سينية تنتج عند تباطؤ إلكترون قرب نواة.","ex":"Bremsstrahlung is produced in the X-ray tube.","exAr":"ينتج إشعاع الكبح في أنبوب الأشعة السينية.","src":"التفاعل مع المادة","lv":"أساسي","c":"c05","l":["tcs85:tcs-2"]},{"id":56,"t":"characteristic x-ray","pos":"عبارة اصطلاحية","ar":"أشعة سينية مميزة","ap":"كاراكتريستِك إكس راي","def":"X-ray with energy specific to the target element.","defAr":"أشعة سينية طاقتها خاصة بعنصر الهدف.","ex":"Characteristic X-rays form sharp peaks.","exAr":"الأشعة المميزة تظهر كقمم حادة.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":57,"t":"auger electron","pos":"عبارة اصطلاحية","ar":"إلكترون أوجيه","ap":"أوجيه إلكترون","def":"An electron ejected instead of emitting an X-ray.","defAr":"إلكترون يُطلق بدل إصدار أشعة سينية.","ex":"Auger electrons have low energy.","exAr":"إلكترونات أوجيه منخفضة الطاقة.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":58,"t":"fission","pos":"اسم","ar":"انشطار","ap":"فِشن","def":"Splitting of a heavy nucleus.","defAr":"انقسام نواة ثقيلة.","ex":"Fission releases neutrons and energy.","exAr":"الانشطار يطلق نيوترونات وطاقة.","src":"الفيزياء النووية","lv":"مهم","c":"c01","l":[]},{"id":59,"t":"fusion","pos":"اسم","ar":"اندماج","ap":"فيوجن","def":"Joining of light nuclei.","defAr":"اتحاد نوى خفيفة.","ex":"Fusion powers the sun.","exAr":"الاندماج يمد الشمس بالطاقة.","src":"الفيزياء النووية","lv":"إضافي","c":"c01","l":[]},{"id":60,"t":"neutron capture","pos":"عبارة اصطلاحية","ar":"التقاط النيوترون","ap":"نيوترون كابتشر","def":"A nucleus absorbs a neutron.","defAr":"نواة تمتص نيوترونًا.","ex":"Neutron capture makes Co-60 from Co-59.","exAr":"التقاط النيوترون ينتج Co-60 من Co-59.","src":"الفيزياء النووية","lv":"مهم","c":"c01","l":[]},{"id":61,"t":"activation","pos":"اسم","ar":"تنشيط (إشعاعي)","ap":"أكتيفيشن","def":"Making a material radioactive by neutrons.","defAr":"جعل مادة مشعة بواسطة النيوترونات.","ex":"Activation creates radioactive material.","exAr":"التنشيط يصنع مادة مشعة.","src":"الفيزياء النووية","lv":"إضافي","c":"c01","l":[]},{"id":62,"t":"moderation","pos":"اسم","ar":"إبطاء (تهدئة) النيوترونات","ap":"مودريشن","def":"Slowing fast neutrons.","defAr":"تقليل سرعة النيوترونات السريعة.","ex":"Water is used for moderation.","exAr":"يُستخدم الماء للإبطاء.","src":"الفيزياء النووية","lv":"إضافي","c":"c01","l":[]},{"id":63,"t":"thermal neutron","pos":"عبارة اصطلاحية","ar":"نيوترون حراري","ap":"ثيرمل نيوترون","def":"A slow neutron with low energy.","defAr":"نيوترون بطيء منخفض الطاقة.","ex":"Thermal neutrons are easily captured.","exAr":"النيوترونات الحرارية تُلتقط بسهولة.","src":"الفيزياء النووية","lv":"إضافي","c":"c01","l":[]},{"id":64,"t":"fast neutron","pos":"عبارة اصطلاحية","ar":"نيوترون سريع","ap":"فاست نيوترون","def":"A neutron with high energy.","defAr":"نيوترون عالي الطاقة.","ex":"Polyethylene slows fast neutrons.","exAr":"البولي إيثيلين يبطئ النيوترونات السريعة.","src":"الفيزياء النووية","lv":"مهم","c":"c01","l":[]},{"id":65,"t":"attenuation","pos":"اسم","ar":"توهين","ap":"أتنيويشن","def":"Reduction of radiation intensity in a material.","defAr":"انخفاض شدة الإشعاع داخل مادة.","ex":"Attenuation depends on thickness.","exAr":"التوهين يعتمد على السُّمك.","src":"التفاعل مع المادة","lv":"أساسي","c":"c05","l":[]},{"id":66,"t":"attenuation coefficient","pos":"عبارة اصطلاحية","ar":"معامل التوهين","ap":"أتنيويشن كوإفيشنت","def":"How strongly a material reduces radiation per unit thickness.","defAr":"مقدار تقليل المادة للإشعاع لكل وحدة سُمك.","ex":"A higher coefficient means better shielding.","exAr":"معامل أعلى يعني تدريعًا أفضل.","src":"التفاعل مع المادة","lv":"مهم","c":"c05","l":[]},{"id":67,"t":"linear attenuation coefficient","pos":"عبارة اصطلاحية","ar":"معامل التوهين الخطي","ap":"لينير أتنيويشن كوإفيشنت","def":"Attenuation per unit length of material.","defAr":"التوهين لكل وحدة طول من المادة.","ex":"It is measured in cm⁻¹.","exAr":"يُقاس بوحدة cm⁻¹.","src":"التفاعل مع المادة","lv":"مهم","c":"c05","l":[]},{"id":68,"t":"half-value layer","pos":"عبارة اصطلاحية","ar":"طبقة نصف التوهين (HVL)","ap":"هاف فاليو لير","def":"Thickness that reduces intensity by half.","defAr":"السُّمك الذي يخفض الشدة إلى النصف.","ex":"One HVL halves the dose rate.","exAr":"طبقة HVL واحدة تخفض معدل الجرعة للنصف.","src":"التدريع","lv":"أساسي","c":"c08","l":[]},{"id":69,"t":"tenth-value layer","pos":"عبارة اصطلاحية","ar":"طبقة عُشر التوهين (TVL)","ap":"تنث فاليو لير","def":"Thickness that reduces intensity to one tenth.","defAr":"السُّمك الذي يخفض الشدة إلى العُشر.","ex":"One TVL gives a tenfold reduction.","exAr":"طبقة TVL واحدة تخفض عشر مرات.","src":"التدريع","lv":"أساسي","c":"c08","l":[]},{"id":70,"t":"buildup factor","pos":"عبارة اصطلاحية","ar":"معامل التراكم","ap":"بِلدأب فاكتر","def":"A factor for scattered radiation behind a shield.","defAr":"معامل يحسب الإشعاع المستطار خلف الدرع.","ex":"Buildup factor increases the calculated dose.","exAr":"معامل التراكم يرفع الجرعة المحسوبة.","src":"التدريع","lv":"إضافي","c":"c08","l":["tcs85:tcs-7"]},{"id":71,"t":"intensity","pos":"اسم","ar":"شدة (الإشعاع)","ap":"إنتنسيتي","def":"Amount of radiation energy passing an area per time.","defAr":"كمية طاقة الإشعاع المارة عبر مساحة في الزمن.","ex":"Intensity falls with distance.","exAr":"تقل الشدة مع المسافة.","src":"الفيزياء","lv":"مهم","c":"c01","l":[]},{"id":72,"t":"inverse square law","pos":"عبارة اصطلاحية","ar":"قانون التربيع العكسي","ap":"إنفيرس سكوير لو","def":"Dose rate falls with the square of the distance.","defAr":"معدل الجرعة يقل بمربع المسافة.","ex":"Double the distance and the dose rate is a quarter.","exAr":"ضاعف المسافة يصبح معدل الجرعة الربع.","src":"الحماية","lv":"أساسي","c":"c08","l":["tcs85:tcs-7"]},{"id":73,"t":"density","pos":"اسم","ar":"كثافة","ap":"دنسيتي","def":"Mass per unit volume.","defAr":"الكتلة لكل وحدة حجم.","ex":"Lead has high density.","exAr":"الرصاص عالي الكثافة.","src":"الفيزياء","lv":"مهم","c":"c01","l":[]},{"id":74,"t":"mean free path","pos":"عبارة اصطلاحية","ar":"متوسط المسار الحر","ap":"مين فري باث","def":"Average distance a photon travels before interacting.","defAr":"متوسط المسافة التي يقطعها فوتون قبل أن يتفاعل.","ex":"Mean free path is 1 over mu.","exAr":"المسار الحر يساوي 1/μ.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":75,"t":"cross section","pos":"عبارة اصطلاحية","ar":"المقطع العرضي (للتفاعل)","ap":"كروس سكشن","def":"Probability measure for an interaction.","defAr":"مقياس لاحتمال حدوث تفاعل.","ex":"Cross section depends on energy.","exAr":"المقطع العرضي يعتمد على الطاقة.","src":"التفاعل مع المادة","lv":"إضافي","c":"c05","l":[]},{"id":76,"t":"exposure","pos":"اسم","ar":"تعرّض / التعرض الإشعاعي","ap":"إكسبوجر","def":"Being subjected to radiation; also the quantity of ionization in air.","defAr":"التعرض للإشعاع، وهو أيضًا كمية التأين في الهواء.","ex":"Exposure is measured in roentgen.","exAr":"يُقاس التعرض بالرونتجن.","src":"الجرعات","lv":"أساسي","c":"c06","l":["tcs85:tcs-3","tcs85:tcs-4","tcs85:tcs-6"]},{"id":77,"t":"dose","pos":"اسم","ar":"جرعة","ap":"دوز","def":"The amount of radiation energy received.","defAr":"كمية الإشعاع التي يتلقاها الجسم.","ex":"The worker's dose was low.","exAr":"كانت جرعة العامل منخفضة.","src":"الجرعات","lv":"أساسي","c":"c06","l":["tcs85:tcs-3","tcs85:tcs-6","tcs85:tcs-12"]},{"id":78,"t":"dose rate","pos":"عبارة اصطلاحية","ar":"معدل الجرعة","ap":"دوز رِيت","def":"Dose received per unit time.","defAr":"الجرعة المستلمة في وحدة الزمن.","ex":"The dose rate is 2 mSv/h.","exAr":"معدل الجرعة 2 mSv/h.","src":"الجرعات","lv":"أساسي","c":"c06","l":["tcs85:tcs-3"]},{"id":79,"t":"absorbed dose","pos":"عبارة اصطلاحية","ar":"الجرعة الممتصة","ap":"أبزوربد دوز","def":"Energy absorbed per kilogram of matter.","defAr":"الطاقة الممتصة لكل كيلوغرام من المادة.","ex":"Absorbed dose is measured in gray.","exAr":"تُقاس الجرعة الممتصة بالغراي.","src":"الجرعات","lv":"أساسي","c":"c06","l":["tcs85:tcs-3"]},{"id":80,"t":"equivalent dose","pos":"عبارة اصطلاحية","ar":"الجرعة المكافئة","ap":"إكويفالنت دوز","def":"Absorbed dose multiplied by the radiation weighting factor.","defAr":"الجرعة الممتصة مضروبة في معامل ترجيح الإشعاع.","ex":"Equivalent dose is measured in sievert.","exAr":"تُقاس الجرعة المكافئة بالسيفرت.","src":"الجرعات","lv":"أساسي","c":"c06","l":[]},{"id":81,"t":"effective dose","pos":"عبارة اصطلاحية","ar":"الجرعة الفعّالة","ap":"إفكتف دوز","def":"Whole-body risk measure weighted by organ sensitivity.","defAr":"مقياس لخطر الجسم كله مرجّح بحساسية الأعضاء.","ex":"The annual effective dose limit is 20 mSv.","exAr":"حد الجرعة الفعالة السنوي 20 mSv.","src":"الجرعات","lv":"أساسي","c":"c06","l":["tcs85:tcs-3"]},{"id":82,"t":"committed dose","pos":"عبارة اصطلاحية","ar":"الجرعة الملتزمة","ap":"كوميتد دوز","def":"Dose received over time from an intake of radioactive material.","defAr":"جرعة تتراكم مع الزمن بعد دخول مادة مشعة للجسم.","ex":"Committed dose applies to internal exposure.","exAr":"الجرعة الملتزمة للتعرض الداخلي.","src":"الجرعات","lv":"إضافي","c":"c06","l":["tcs85:tcs-3"]},{"id":83,"t":"collective dose","pos":"عبارة اصطلاحية","ar":"الجرعة الجماعية","ap":"كوليكتف دوز","def":"Sum of doses of a group of people.","defAr":"مجموع جرعات مجموعة من الأشخاص.","ex":"Collective dose is in man-sievert.","exAr":"الجرعة الجماعية بوحدة رجل-سيفرت.","src":"الجرعات","lv":"إضافي","c":"c06","l":["tcs85:tcs-3"]},{"id":84,"t":"cumulative dose","pos":"عبارة اصطلاحية","ar":"الجرعة التراكمية","ap":"كيوميوليتف دوز","def":"Total dose added up over time.","defAr":"الجرعة الكلية المجمعة عبر الزمن.","ex":"Records show the cumulative dose.","exAr":"تُظهر السجلات الجرعة التراكمية.","src":"الجرعات","lv":"مهم","c":"c06","l":[]},{"id":85,"t":"dose limit","pos":"عبارة اصطلاحية","ar":"حد الجرعة","ap":"دوز لِمِت","def":"The maximum dose allowed by regulation.","defAr":"أقصى جرعة تسمح بها اللوائح.","ex":"Never exceed the dose limit.","exAr":"لا تتجاوز حد الجرعة أبدًا.","src":"الجرعات","lv":"أساسي","c":"c09","l":["tcs85:tcs-6","nrrc:nrrc-2","nrrc:nrrc-6"]},{"id":86,"t":"dose constraint","pos":"عبارة اصطلاحية","ar":"قيد الجرعة","ap":"دوز كونستريْنت","def":"A planned upper value for optimization of one source.","defAr":"حد أعلى مخطط له لتحسين الحماية من مصدر معين.","ex":"A dose constraint is below the limit.","exAr":"قيد الجرعة أقل من الحد.","src":"الجرعات","lv":"مهم","c":"c09","l":["tcs85:tcs-6"]},{"id":87,"t":"occupational exposure","pos":"عبارة اصطلاحية","ar":"التعرض المهني","ap":"أوكيوبيشنل إكسبوجر","def":"Exposure of workers during their work.","defAr":"تعرض العاملين أثناء عملهم.","ex":"Radiographers have occupational exposure.","exAr":"مصورو الأشعة لديهم تعرض مهني.","src":"الجرعات","lv":"أساسي","c":"c09","l":[]},{"id":88,"t":"public exposure","pos":"عبارة اصطلاحية","ar":"تعرض الجمهور","ap":"بَبلِك إكسبوجر","def":"Exposure of members of the public.","defAr":"تعرض أفراد الجمهور.","ex":"Public exposure limits are lower.","exAr":"حدود تعرض الجمهور أقل.","src":"الجرعات","lv":"مهم","c":"c09","l":[]},{"id":89,"t":"medical exposure","pos":"عبارة اصطلاحية","ar":"التعرض الطبي","ap":"ميديكل إكسبوجر","def":"Exposure of patients during diagnosis or treatment.","defAr":"تعرض المرضى أثناء التشخيص أو العلاج.","ex":"Medical exposure is not in radiography.","exAr":"التعرض الطبي ليس في التصوير الصناعي.","src":"الجرعات","lv":"إضافي","c":"c09","l":[]},{"id":90,"t":"external exposure","pos":"عبارة اصطلاحية","ar":"تعرض خارجي","ap":"إكسترنال إكسبوجر","def":"Radiation from a source outside the body.","defAr":"إشعاع من مصدر خارج الجسم.","ex":"Time, distance and shielding reduce external exposure.","exAr":"الزمن والمسافة والتدريع تقلل التعرض الخارجي.","src":"الجرعات","lv":"أساسي","c":"c06","l":[]},{"id":91,"t":"internal exposure","pos":"عبارة اصطلاحية","ar":"تعرض داخلي","ap":"إنترنال إكسبوجر","def":"Radiation from material inside the body.","defAr":"إشعاع من مادة مشعة داخل الجسم.","ex":"Ingestion causes internal exposure.","exAr":"الابتلاع يسبب تعرضًا داخليًا.","src":"الجرعات","lv":"أساسي","c":"c06","l":[]},{"id":92,"t":"whole body","pos":"عبارة اصطلاحية","ar":"الجسم كله","ap":"هول بودي","def":"The entire body.","defAr":"الجسم بأكمله.","ex":"Whole-body dose is measured by a badge.","exAr":"جرعة الجسم كله تقيسها شارة القياس.","src":"الجرعات","lv":"مهم","c":"c06","l":[]},{"id":93,"t":"extremities","pos":"اسم","ar":"الأطراف","ap":"إكستريميتيز","def":"Hands and feet.","defAr":"اليدان والقدمان.","ex":"Extremities have higher dose limits.","exAr":"الأطراف لها حدود جرعة أعلى.","src":"الجرعات","lv":"مهم","c":"c06","l":[]},{"id":94,"t":"lens of the eye","pos":"عبارة اصطلاحية","ar":"عدسة العين","ap":"لنز أوف ذي آي","def":"The part of the eye that can develop cataracts.","defAr":"جزء العين الذي قد تصيبه الساد (الكتاراكت).","ex":"The lens of the eye has its own limit.","exAr":"لعدسة العين حد خاص بها.","src":"الجرعات","lv":"مهم","c":"c06","l":[]},{"id":95,"t":"radiation weighting factor","pos":"عبارة اصطلاحية","ar":"معامل ترجيح الإشعاع (wR)","ap":"ريديايشن ويتنغ فاكتر","def":"A factor for how harmful each radiation type is.","defAr":"معامل يعكس خطورة نوع الإشعاع.","ex":"Alpha has a high weighting factor.","exAr":"لجسيمات ألفا معامل ترجيح عالٍ.","src":"الجرعات","lv":"مهم","c":"c06","l":[]},{"id":96,"t":"tissue weighting factor","pos":"عبارة اصطلاحية","ar":"معامل ترجيح النسيج (wT)","ap":"تِشو ويتنغ فاكتر","def":"A factor for how sensitive each organ is.","defAr":"معامل يعكس حساسية العضو للإشعاع.","ex":"Tissue weighting factors sum to one.","exAr":"مجموع معاملات ترجيح الأنسجة يساوي 1.","src":"الجرعات","lv":"إضافي","c":"c06","l":[]},{"id":97,"t":"kerma","pos":"اسم","ar":"كيرما (طاقة حركية مفرَّغة)","ap":"كيرما","def":"Kinetic energy released per unit mass.","defAr":"الطاقة الحركية المحررة لكل وحدة كتلة.","ex":"Kerma is measured in gray.","exAr":"تُقاس الكيرما بالغراي.","src":"الجرعات","lv":"إضافي","c":"c06","l":["tcs85:tcs-3"]},{"id":98,"t":"becquerel","pos":"اسم","ar":"بيكريل (Bq)","ap":"بيكريل","def":"SI unit of activity: one decay per second.","defAr":"وحدة النشاط في النظام الدولي: تحلل واحد في الثانية.","ex":"One Bq equals one decay per second.","exAr":"1 Bq يساوي تحللًا في الثانية.","src":"الوحدات","lv":"أساسي","c":"c06","l":[]},{"id":99,"t":"curie","pos":"اسم","ar":"كوري (Ci)","ap":"كيوري","def":"Old unit of activity equal to 3.7×10¹⁰ Bq.","defAr":"وحدة نشاط قديمة تساوي 3.7×10¹⁰ Bq.","ex":"One curie is 37 GBq.","exAr":"الكوري الواحد يساوي 37 GBq.","src":"الوحدات","lv":"أساسي","c":"c06","l":[]},{"id":100,"t":"gray","pos":"اسم","ar":"غراي (Gy)","ap":"غراي","def":"SI unit of absorbed dose: one joule per kilogram.","defAr":"وحدة الجرعة الممتصة: جول لكل كيلوغرام.","ex":"One gray equals 100 rad.","exAr":"1 Gy يساوي 100 rad.","src":"الوحدات","lv":"أساسي","c":"c06","l":[]},{"id":101,"t":"sievert","pos":"اسم","ar":"سيفرت (Sv)","ap":"سيفرت","def":"SI unit of equivalent and effective dose.","defAr":"وحدة الجرعة المكافئة والفعالة.","ex":"One sievert equals 100 rem.","exAr":"1 Sv يساوي 100 rem.","src":"الوحدات","lv":"أساسي","c":"c06","l":[]},{"id":102,"t":"rad","pos":"اسم","ar":"راد","ap":"راد","def":"Old unit of absorbed dose; 1 rad = 0.01 Gy.","defAr":"وحدة قديمة للجرعة الممتصة.","ex":"100 rad equals 1 Gy.","exAr":"100 راد = 1 Gy.","src":"الوحدات","lv":"مهم","c":"c06","l":[]},{"id":103,"t":"rem","pos":"اسم","ar":"ريم","ap":"ريم","def":"Old unit of equivalent dose; 1 rem = 0.01 Sv.","defAr":"وحدة قديمة للجرعة المكافئة.","ex":"50 rem equals 0.5 Sv.","exAr":"50 ريم = 0.5 Sv.","src":"الوحدات","lv":"أساسي","c":"c06","l":[]},{"id":104,"t":"roentgen","pos":"اسم","ar":"رونتجن (R)","ap":"رونتجن","def":"Old unit of exposure in air.","defAr":"وحدة قديمة للتعرض في الهواء.","ex":"One roentgen is about 0.01 Sv for gamma.","exAr":"الرونتجن الواحد يقارب 0.01 Sv لأشعة غاما.","src":"الوحدات","lv":"مهم","c":"c06","l":[]},{"id":105,"t":"stochastic effect","pos":"عبارة اصطلاحية","ar":"أثر عشوائي (احتمالي)","ap":"ستوكاستِك إفكت","def":"An effect whose probability rises with dose, without a threshold.","defAr":"أثر يزداد احتماله بزيادة الجرعة ولا حد له.","ex":"Cancer is a stochastic effect.","exAr":"السرطان أثر عشوائي.","src":"الآثار الحيوية","lv":"أساسي","c":"x01","l":["tcs85:tcs-5"]},{"id":106,"t":"deterministic effect","pos":"عبارة اصطلاحية","ar":"أثر حتمي (نسيجي)","ap":"ديترمنستِك إفكت","def":"An effect with a threshold whose severity rises with dose.","defAr":"أثر له عتبة وتزداد شدته بزيادة الجرعة.","ex":"Skin burns are deterministic effects.","exAr":"حروق الجلد أثر حتمي.","src":"الآثار الحيوية","lv":"أساسي","c":"x01","l":["tcs85:tcs-5"]},{"id":107,"t":"threshold","pos":"اسم","ar":"عتبة","ap":"ثريشهولد","def":"The dose below which an effect does not occur.","defAr":"الجرعة التي لا يحدث الأثر تحتها.","ex":"Deterministic effects have a threshold.","exAr":"للآثار الحتمية عتبة.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":["tcs85:tcs-5"]},{"id":108,"t":"linear no-threshold","pos":"عبارة اصطلاحية","ar":"النموذج الخطي بلا عتبة (LNT)","ap":"لينير نو ثريشهولد","def":"Model that risk rises linearly with dose, even at low doses.","defAr":"نموذج يفترض أن الخطر يزداد خطيًا حتى مع الجرعات المنخفضة.","ex":"LNT is the basis of ALARA.","exAr":"LNT هو أساس مبدأ ALARA.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":["tcs85:tcs-5"]},{"id":109,"t":"acute","pos":"صفة","ar":"حاد","ap":"أكيوت","def":"Occurring quickly after a high dose.","defAr":"يحدث سريعًا بعد جرعة عالية.","ex":"Acute radiation sickness needs a high dose.","exAr":"مرض الإشعاع الحاد يحتاج جرعة عالية.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":["tcs85:tcs-5"]},{"id":110,"t":"chronic","pos":"صفة","ar":"مزمن","ap":"كرونِك","def":"Occurring over a long time.","defAr":"يحدث على مدى طويل.","ex":"Chronic exposure is spread over years.","exAr":"التعرض المزمن يمتد لسنوات.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":[]},{"id":111,"t":"acute radiation syndrome","pos":"عبارة اصطلاحية","ar":"متلازمة الإشعاع الحادة (ARS)","ap":"أكيوت ريديايشن سندروم","def":"Illness after a high whole-body dose in a short time.","defAr":"مرض يحدث بعد جرعة عالية للجسم كله في وقت قصير.","ex":"Nausea can be an early sign of ARS.","exAr":"الغثيان قد يكون علامة مبكرة.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":["tcs85:tcs-5"]},{"id":112,"t":"erythema","pos":"اسم","ar":"احمرار الجلد (حمامى)","ap":"إريثيما","def":"Reddening of the skin from radiation.","defAr":"احمرار الجلد بسبب الإشعاع.","ex":"Erythema is a skin effect.","exAr":"الحمامى أثر جلدي.","src":"الآثار الحيوية","lv":"إضافي","c":"x01","l":["tcs85:tcs-5"]},{"id":113,"t":"cataract","pos":"اسم","ar":"ساد (كتاراكت)","ap":"كاتاراكت","def":"Clouding of the eye lens.","defAr":"تعتّم عدسة العين.","ex":"Radiation may cause cataracts.","exAr":"قد يسبب الإشعاع الساد.","src":"الآثار الحيوية","lv":"إضافي","c":"x01","l":[]},{"id":114,"t":"cancer","pos":"اسم","ar":"سرطان","ap":"كانسر","def":"Uncontrolled growth of cells.","defAr":"نمو غير منضبط للخلايا.","ex":"Radiation can increase cancer risk.","exAr":"الإشعاع قد يزيد خطر السرطان.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":[]},{"id":115,"t":"hereditary","pos":"صفة","ar":"وراثي","ap":"هيريديتري","def":"Passed from parents to children.","defAr":"ينتقل من الآباء إلى الأبناء.","ex":"Hereditary effects appear in offspring.","exAr":"الآثار الوراثية تظهر في الذرية.","src":"الآثار الحيوية","lv":"إضافي","c":"x01","l":[]},{"id":116,"t":"somatic","pos":"صفة","ar":"جسدي","ap":"سوماتِك","def":"Affecting the body of the exposed person.","defAr":"يصيب جسد الشخص المتعرض نفسه.","ex":"Somatic effects appear in the exposed person.","exAr":"الآثار الجسدية تظهر في المتعرض.","src":"الآثار الحيوية","lv":"إضافي","c":"x01","l":[]},{"id":117,"t":"radiosensitive","pos":"صفة","ar":"حساس للإشعاع","ap":"ريديوسنسِتف","def":"Easily damaged by radiation.","defAr":"سهل التضرر بالإشعاع.","ex":"Bone marrow is radiosensitive.","exAr":"نخاع العظم حساس للإشعاع.","src":"الآثار الحيوية","lv":"إضافي","c":"x01","l":[]},{"id":118,"t":"fetus","pos":"اسم","ar":"جنين","ap":"فيتس","def":"An unborn baby.","defAr":"طفل لم يولد بعد.","ex":"The fetus must be protected.","exAr":"يجب حماية الجنين.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":[]},{"id":119,"t":"pregnancy","pos":"اسم","ar":"حمل","ap":"بريغننسي","def":"The state of carrying a fetus.","defAr":"حالة حمل الجنين.","ex":"Declare pregnancy to the employer.","exAr":"أبلغ صاحب العمل بالحمل.","src":"الآثار الحيوية","lv":"مهم","c":"x01","l":[]},{"id":120,"t":"radiation protection","pos":"عبارة اصطلاحية","ar":"الحماية من الإشعاع","ap":"ريديايشن بروتكشن","def":"Measures to protect people from radiation.","defAr":"إجراءات لوقاية الناس من الإشعاع.","ex":"Radiation protection is required for all workers.","exAr":"الحماية من الإشعاع مطلوبة لكل العاملين.","src":"الحماية","lv":"أساسي","c":"c08","l":["tcs85:tcs-10","tcs85:tcs-1","nrrc:nrrc-1"]},{"id":121,"t":"radiation safety","pos":"عبارة اصطلاحية","ar":"السلامة الإشعاعية","ap":"ريديايشن سيفتي","def":"Protecting people and keeping sources safe.","defAr":"حماية الناس وحفظ المصادر بأمان.","ex":"Radiation safety covers sources and people.","exAr":"السلامة الإشعاعية تشمل المصادر والأشخاص.","src":"الحماية","lv":"أساسي","c":"c08","l":["nrrc:nrrc-2"]},{"id":122,"t":"ALARA","pos":"اختصار","ar":"ألارا (أدنى مستوى معقول ممكن)","ap":"ألارا","def":"As Low As Reasonably Achievable.","defAr":"أدنى ما يمكن تحقيقه بشكل معقول.","ex":"Follow ALARA in all work.","exAr":"اتبع ألارا في كل عمل.","src":"الحماية","lv":"أساسي","c":"c08","l":["tcs85:tcs-6"]},{"id":123,"t":"justification","pos":"اسم","ar":"التبرير","ap":"جستفكيشن","def":"The benefit must outweigh the harm.","defAr":"يجب أن تفوق الفائدة الضرر.","ex":"Justification is the first principle.","exAr":"التبرير هو المبدأ الأول.","src":"الحماية","lv":"أساسي","c":"c08","l":["tcs85:tcs-6"]},{"id":124,"t":"optimization","pos":"اسم","ar":"الأمثلة (التحسين)","ap":"أوبتمايزيشن","def":"Keeping doses as low as reasonably achievable.","defAr":"إبقاء الجرعات في أدنى مستوى معقول.","ex":"Optimization is the second principle.","exAr":"الأمثلة هو المبدأ الثاني.","src":"الحماية","lv":"أساسي","c":"c08","l":["tcs85:tcs-6"]},{"id":125,"t":"dose limitation","pos":"عبارة اصطلاحية","ar":"تحديد الجرعة","ap":"دوز لمتيشن","def":"Doses must not exceed the set limits.","defAr":"ألا تتجاوز الجرعات الحدود المقررة.","ex":"Dose limitation is the third principle.","exAr":"تحديد الجرعة هو المبدأ الثالث.","src":"الحماية","lv":"أساسي","c":"c09","l":[]},{"id":126,"t":"time","pos":"اسم","ar":"الزمن","ap":"تايم","def":"Less time near a source means less dose.","defAr":"كلما قل الزمن قرب المصدر قلت الجرعة.","ex":"Reduce the time near the source.","exAr":"قلل الزمن قرب المصدر.","src":"الحماية","lv":"أساسي","c":"c08","l":[]},{"id":127,"t":"distance","pos":"اسم","ar":"المسافة","ap":"ديستنس","def":"More distance means less dose.","defAr":"زيادة المسافة تقلل الجرعة.","ex":"Increase the distance from the source.","exAr":"زد المسافة عن المصدر.","src":"الحماية","lv":"أساسي","c":"c08","l":[]},{"id":128,"t":"shielding","pos":"اسم","ar":"تدريع","ap":"شيلدنغ","def":"Material placed to reduce radiation.","defAr":"مادة توضع لتقليل الإشعاع.","ex":"Lead is used for shielding.","exAr":"يُستخدم الرصاص للتدريع.","src":"الحماية","lv":"أساسي","c":"c08","l":[]},{"id":129,"t":"shield","pos":"اسم / فعل","ar":"درع / يدرّع","ap":"شيلد","def":"A barrier that absorbs radiation.","defAr":"حاجز يمتص الإشعاع.","ex":"A shield protects the worker.","exAr":"الدرع يحمي العامل.","src":"الحماية","lv":"أساسي","c":"c08","l":[]},{"id":130,"t":"lead","pos":"اسم","ar":"رصاص","ap":"ليد","def":"A dense metal used to shield gamma and X-rays.","defAr":"فلز كثيف يُستخدم لتدريع غاما والسينية.","ex":"Lead shields gamma rays well.","exAr":"الرصاص يحمي جيدًا من غاما.","src":"الحماية","lv":"أساسي","c":"c08","l":[]},{"id":131,"t":"concrete","pos":"اسم","ar":"خرسانة","ap":"كونكريت","def":"Building material used for shielding walls.","defAr":"مادة بناء تُستخدم لجدران التدريع.","ex":"Concrete walls shield the bay.","exAr":"جدران الخرسانة تدرّع الحجرة.","src":"الحماية","lv":"مهم","c":"c08","l":[]},{"id":132,"t":"depleted uranium","pos":"عبارة اصطلاحية","ar":"يورانيوم مستنفد","ap":"ديبلتد يورانيوم","def":"Dense uranium used in some exposure device shielding.","defAr":"يورانيوم كثيف يدخل في تدريع بعض أجهزة التعريض.","ex":"Depleted uranium shields the source.","exAr":"اليورانيوم المستنفد يدرّع المصدر.","src":"الحماية","lv":"إضافي","c":"c08","l":["tcs85:tcs-4"]},{"id":133,"t":"polyethylene","pos":"اسم","ar":"بولي إيثيلين","ap":"بولي إيثيلين","def":"Hydrogen-rich plastic that slows neutrons.","defAr":"بلاستيك غني بالهيدروجين يبطئ النيوترونات.","ex":"Polyethylene shields neutrons.","exAr":"يدرّع البولي إيثيلين النيوترونات.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":134,"t":"controlled area","pos":"عبارة اصطلاحية","ar":"منطقة مراقبة","ap":"كونترولد إيريا","def":"An area with special protection rules and access control.","defAr":"منطقة لها قواعد حماية وتحكم في الدخول.","ex":"Only authorized people enter a controlled area.","exAr":"لا يدخل المنطقة المراقبة إلا المصرح لهم.","src":"المناطق","lv":"أساسي","c":"c10","l":["tcs85:tcs-10"]},{"id":135,"t":"supervised area","pos":"عبارة اصطلاحية","ar":"منطقة خاضعة للإشراف","ap":"سوبرفايزد إيريا","def":"An area kept under review for exposure conditions.","defAr":"منطقة تُراجَع فيها ظروف التعرض.","ex":"A supervised area is less strict.","exAr":"المنطقة الخاضعة للإشراف أقل تشددًا.","src":"المناطق","lv":"مهم","c":"c10","l":["tcs85:tcs-10"]},{"id":136,"t":"restricted area","pos":"عبارة اصطلاحية","ar":"منطقة محظورة","ap":"ريستريكتد إيريا","def":"An area with limited access.","defAr":"منطقة يقيَّد الدخول إليها.","ex":"Keep people out of the restricted area.","exAr":"أبعد الناس عن المنطقة المحظورة.","src":"المناطق","lv":"مهم","c":"c10","l":[]},{"id":137,"t":"boundary","pos":"اسم","ar":"حدّ (حدود المنطقة)","ap":"باوندري","def":"The limit of a controlled area.","defAr":"حدود المنطقة المراقبة.","ex":"Mark the boundary with tape.","exAr":"حدد الحدود بشريط.","src":"المناطق","lv":"مهم","c":"c10","l":[]},{"id":138,"t":"barrier","pos":"اسم","ar":"حاجز","ap":"باريير","def":"A physical block to keep people away.","defAr":"عائق مادي لإبعاد الناس.","ex":"Place a barrier around the area.","exAr":"ضع حاجزًا حول المنطقة.","src":"المناطق","lv":"مهم","c":"c10","l":["tcs85:tcs-7"]},{"id":139,"t":"warning sign","pos":"عبارة اصطلاحية","ar":"لافتة تحذير","ap":"وورنغ ساين","def":"A sign that warns of radiation.","defAr":"لافتة تنبه لوجود إشعاع.","ex":"Post a warning sign.","exAr":"ضع لافتة تحذير.","src":"المناطق","lv":"مهم","c":"c10","l":[]},{"id":140,"t":"trefoil","pos":"اسم","ar":"رمز الإشعاع (ثلاثي الأوراق)","ap":"تريفويل","def":"The three-bladed radiation symbol.","defAr":"رمز الإشعاع الدولي ثلاثي الأوراق.","ex":"The trefoil appears on the device.","exAr":"يظهر الرمز على الجهاز.","src":"المناطق","lv":"مهم","c":"c10","l":[]},{"id":141,"t":"alarm","pos":"اسم","ar":"إنذار","ap":"ألارم","def":"A signal that warns of danger.","defAr":"إشارة تنبه إلى خطر.","ex":"The alarm sounds at high dose rate.","exAr":"ينطلق الإنذار عند معدل جرعة عالٍ.","src":"المناطق","lv":"مهم","c":"c10","l":[]},{"id":142,"t":"contamination","pos":"اسم","ar":"تلوث إشعاعي","ap":"كونتامينيشن","def":"Unwanted radioactive material on surfaces or people.","defAr":"مادة مشعة غير مرغوبة على الأسطح أو الأشخاص.","ex":"Contamination can spread by hand.","exAr":"التلوث قد ينتشر باليد.","src":"التلوث","lv":"أساسي","c":"x02","l":["tcs85:tcs-2","tcs85:tcs-11"]},{"id":143,"t":"contaminated","pos":"صفة","ar":"ملوَّث","ap":"كونتامينيتد","def":"Having radioactive material on it.","defAr":"عليه مادة مشعة.","ex":"Wash the contaminated area.","exAr":"اغسل المنطقة الملوثة.","src":"التلوث","lv":"مهم","c":"x02","l":[]},{"id":144,"t":"irradiation","pos":"اسم","ar":"تشعيع (التعرض للإشعاع)","ap":"إيرِديايشن","def":"Exposing something to radiation without touching radioactive material.","defAr":"تعريض شيء للإشعاع دون ملامسة مادة مشعة.","ex":"Irradiation does not make you radioactive.","exAr":"التشعيع لا يجعلك مشعًا.","src":"التلوث","lv":"أساسي","c":"x02","l":[]},{"id":145,"t":"irradiated","pos":"صفة","ar":"مُشعَّع","ap":"إيرِديايتد","def":"Exposed to radiation.","defAr":"تعرض للإشعاع.","ex":"The sample was irradiated.","exAr":"عُرّضت العينة للإشعاع.","src":"التلوث","lv":"إضافي","c":"x02","l":[]},{"id":146,"t":"decontamination","pos":"اسم","ar":"إزالة التلوث","ap":"ديكونتامينيشن","def":"Removing radioactive contamination.","defAr":"إزالة التلوث الإشعاعي.","ex":"Decontamination uses water and soap.","exAr":"إزالة التلوث بالماء والصابون.","src":"التلوث","lv":"مهم","c":"x02","l":[]},{"id":147,"t":"ingestion","pos":"اسم","ar":"ابتلاع","ap":"إنجستشن","def":"Taking material in through the mouth.","defAr":"دخول مادة عن طريق الفم.","ex":"Ingestion causes internal dose.","exAr":"الابتلاع يسبب جرعة داخلية.","src":"التلوث","lv":"مهم","c":"x02","l":[]},{"id":148,"t":"inhalation","pos":"اسم","ar":"استنشاق","ap":"إنهاليشن","def":"Breathing in material.","defAr":"دخول مادة عن طريق التنفس.","ex":"Inhalation of dust is dangerous.","exAr":"استنشاق الغبار خطر.","src":"التلوث","lv":"مهم","c":"x02","l":[]},{"id":149,"t":"intake","pos":"اسم","ar":"امتصاص إلى الجسم (مدخول)","ap":"إنتيك","def":"Radioactive material taken into the body.","defAr":"دخول مادة مشعة للجسم.","ex":"Intake can be measured by bioassay.","exAr":"يمكن قياس المدخول بالفحص الحيوي.","src":"التلوث","lv":"إضافي","c":"x02","l":[]},{"id":150,"t":"bioassay","pos":"اسم","ar":"فحص حيوي (تحليل عينات الجسم)","ap":"بايو أسّي","def":"Measuring radioactivity in body samples.","defAr":"قياس النشاط الإشعاعي في عينات الجسم.","ex":"Bioassay checks internal contamination.","exAr":"الفحص الحيوي يكشف التلوث الداخلي.","src":"التلوث","lv":"إضافي","c":"x02","l":[]},{"id":151,"t":"wipe test","pos":"عبارة اصطلاحية","ar":"اختبار المسح (اختبار التسرب)","ap":"وايب تست","def":"Wiping a surface to check for leaking radioactivity.","defAr":"مسح سطح للتحقق من وجود تسرب إشعاعي.","ex":"A wipe test checks a sealed source for leakage.","exAr":"اختبار المسح يتحقق من تسرب المصدر المختوم.","src":"التلوث","lv":"مهم","c":"c12","l":[]},{"id":152,"t":"leak test","pos":"عبارة اصطلاحية","ar":"اختبار التسرب","ap":"ليك تست","def":"A test to check that a sealed source does not leak.","defAr":"اختبار للتأكد من عدم تسرب المصدر المختوم.","ex":"Do a leak test regularly.","exAr":"أجرِ اختبار التسرب دوريًا.","src":"التلوث","lv":"مهم","c":"c12","l":["tcs85:tcs-10"]},{"id":153,"t":"leakage","pos":"اسم","ar":"تسرب","ap":"ليكج","def":"Radiation or material escaping from a container.","defAr":"إشعاع أو مادة تخرج من الوعاء.","ex":"Leakage from the container must be checked.","exAr":"يجب فحص التسرب من الوعاء.","src":"التلوث","lv":"مهم","c":"x02","l":[]},{"id":154,"t":"spill","pos":"اسم","ar":"انسكاب","ap":"سبِل","def":"Accidental release of radioactive liquid.","defAr":"تسرب عرضي لسائل مشع.","ex":"Clean up the spill quickly.","exAr":"نظّف الانسكاب سريعًا.","src":"التلوث","lv":"مهم","c":"x02","l":[]},{"id":155,"t":"background radiation","pos":"عبارة اصطلاحية","ar":"إشعاع الخلفية","ap":"باكغراوند ريديايشن","def":"Natural radiation always present around us.","defAr":"إشعاع طبيعي موجود دائمًا حولنا.","ex":"Subtract the background radiation.","exAr":"اطرح إشعاع الخلفية.","src":"الحماية","lv":"مهم","c":"c08","l":[]},{"id":156,"t":"cosmic radiation","pos":"عبارة اصطلاحية","ar":"إشعاع كوني","ap":"كوزمِك ريديايشن","def":"Radiation that comes from space.","defAr":"إشعاع قادم من الفضاء.","ex":"Cosmic radiation is natural background.","exAr":"الإشعاع الكوني خلفية طبيعية.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":157,"t":"radon","pos":"اسم","ar":"رادون","ap":"رايدون","def":"A natural radioactive gas.","defAr":"غاز مشع طبيعي.","ex":"Radon is a natural source of exposure.","exAr":"الرادون مصدر طبيعي للتعرض.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":158,"t":"natural source","pos":"عبارة اصطلاحية","ar":"مصدر طبيعي","ap":"ناتشرل سورس","def":"A source of radiation from nature.","defAr":"مصدر إشعاع من الطبيعة.","ex":"Radon is a natural source.","exAr":"الرادون مصدر طبيعي.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":159,"t":"artificial source","pos":"عبارة اصطلاحية","ar":"مصدر صناعي","ap":"آرتفشل سورس","def":"A source made by humans.","defAr":"مصدر من صنع الإنسان.","ex":"Co-60 is an artificial source.","exAr":"Co-60 مصدر صناعي.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":160,"t":"radiological emergency","pos":"عبارة اصطلاحية","ar":"طارئ إشعاعي","ap":"ريديولوجكل إمرجنسي","def":"An event with a risk of radiation harm.","defAr":"حدث فيه خطر ضرر إشعاعي.","ex":"Call the RPO in a radiological emergency.","exAr":"اتصل بمسؤول الحماية عند الطارئ الإشعاعي.","src":"الطوارئ","lv":"أساسي","c":"c13","l":["tcs85:tcs-12"]},{"id":161,"t":"emergency plan","pos":"عبارة اصطلاحية","ar":"خطة طوارئ","ap":"إمرجنسي بلان","def":"A written plan for handling an emergency.","defAr":"خطة مكتوبة للتعامل مع حالة طارئة.","ex":"Practice the emergency plan.","exAr":"تدرّب على خطة الطوارئ.","src":"الطوارئ","lv":"أساسي","c":"c13","l":["tcs85:tcs-12"]},{"id":162,"t":"incident","pos":"اسم","ar":"حادثة (واقعة)","ap":"إنسدنت","def":"An unplanned event with possible harm.","defAr":"حدث غير مخطط له وقد يسبب ضررًا.","ex":"Report every incident.","exAr":"أبلغ عن كل حادثة.","src":"الطوارئ","lv":"أساسي","c":"c13","l":[]},{"id":163,"t":"accident","pos":"اسم","ar":"حادث","ap":"أكسدنت","def":"An unintended event causing harm.","defAr":"حدث غير مقصود يسبب ضررًا.","ex":"The accident caused overexposure.","exAr":"سبب الحادث تعرضًا زائدًا.","src":"الطوارئ","lv":"مهم","c":"c13","l":[]},{"id":164,"t":"overexposure","pos":"اسم","ar":"تعرض زائد","ap":"أوفر إكسبوجر","def":"Dose above the allowed limit.","defAr":"جرعة تفوق الحد المسموح.","ex":"Overexposure must be investigated.","exAr":"يجب التحقيق في التعرض الزائد.","src":"الطوارئ","lv":"مهم","c":"c13","l":["tcs85:tcs-12"]},{"id":165,"t":"investigation","pos":"اسم","ar":"تحقيق","ap":"إنفستغيشن","def":"Finding the cause of an event.","defAr":"معرفة سبب الحدث.","ex":"An investigation follows an incident.","exAr":"يتبع الحادثةَ تحقيقٌ.","src":"الطوارئ","lv":"مهم","c":"c13","l":["tcs85:tcs-6"]},{"id":166,"t":"lost source","pos":"عبارة اصطلاحية","ar":"مصدر مفقود","ap":"لوست سورس","def":"A source whose location is unknown.","defAr":"مصدر لا يُعرف مكانه.","ex":"Report a lost source at once.","exAr":"أبلغ فورًا عن المصدر المفقود.","src":"الطوارئ","lv":"أساسي","c":"c13","l":[]},{"id":167,"t":"stolen","pos":"صفة","ar":"مسروق","ap":"ستولن","def":"Taken without permission.","defAr":"مأخوذ بلا إذن.","ex":"Notify authorities of a stolen source.","exAr":"أبلغ السلطات عن المصدر المسروق.","src":"الطوارئ","lv":"مهم","c":"c13","l":[]},{"id":168,"t":"evacuate","pos":"فعل","ar":"يُخلي","ap":"إيفاكيويت","def":"To leave an area for safety.","defAr":"مغادرة منطقة للسلامة.","ex":"Evacuate the area quickly.","exAr":"أخلِ المنطقة بسرعة.","src":"الطوارئ","lv":"مهم","c":"c13","l":[]},{"id":169,"t":"isolate","pos":"فعل","ar":"يعزل","ap":"آيسوليت","def":"To keep separate from others.","defAr":"فصل وإبعاد عن الآخرين.","ex":"Isolate the area.","exAr":"اعزل المنطقة.","src":"الطوارئ","lv":"مهم","c":"c13","l":[]},{"id":170,"t":"industrial radiography","pos":"عبارة اصطلاحية","ar":"التصوير الإشعاعي الصناعي","ap":"إندستريال ريديوغرافي","def":"Using radiation to see inside materials and welds.","defAr":"استخدام الإشعاع لرؤية داخل المواد واللحامات.","ex":"Industrial radiography uses X-rays or gamma rays.","exAr":"يستخدم التصوير الصناعي أشعة سينية أو غاما.","src":"التصوير الإشعاعي","lv":"أساسي","c":"c11","l":["ssg11:ssg-1"]},{"id":171,"t":"radiography","pos":"اسم","ar":"تصوير إشعاعي","ap":"ريديوغرافي","def":"Making an image with radiation.","defAr":"إنتاج صورة بالإشعاع.","ex":"Radiography checks weld quality.","exAr":"التصوير الإشعاعي يفحص جودة اللحام.","src":"التصوير الإشعاعي","lv":"أساسي","c":"c11","l":["ssg11:ssg-1","tcs85:tcs-4","ssg11:ssg-10"]},{"id":172,"t":"radiographer","pos":"اسم","ar":"مصوّر إشعاعي (فني التصوير)","ap":"ريديوغرافر","def":"A trained person who performs radiography.","defAr":"شخص مدرب ينفذ التصوير الإشعاعي.","ex":"The radiographer wears a dosimeter.","exAr":"يرتدي المصوّر مقياس جرعات.","src":"التصوير الإشعاعي","lv":"أساسي","c":"c11","l":[]},{"id":173,"t":"radiographic","pos":"صفة","ar":"إشعاعي (متعلق بالتصوير)","ap":"ريديوغرافِك","def":"Related to radiography.","defAr":"متعلق بالتصوير الإشعاعي.","ex":"Check the radiographic film.","exAr":"افحص فيلم التصوير.","src":"التصوير الإشعاعي","lv":"إضافي","c":"c11","l":[]},{"id":174,"t":"non-destructive testing","pos":"عبارة اصطلاحية","ar":"الفحص غير الإتلافي (NDT)","ap":"نون ديستركتف تستنغ","def":"Inspection that does not damage the part.","defAr":"فحص لا يتلف القطعة.","ex":"NDT includes radiography.","exAr":"الفحص غير الإتلافي يشمل التصوير الإشعاعي.","src":"التصوير الإشعاعي","lv":"أساسي","c":"c11","l":[]},{"id":175,"t":"weld","pos":"اسم","ar":"لحام","ap":"ولد","def":"A joint made by melting metal.","defAr":"وصلة معدنية تتم بصهر المعدن.","ex":"The weld was radiographed.","exAr":"صُوّر اللحام إشعاعيًا.","src":"التصوير الإشعاعي","lv":"أساسي","c":"c11","l":[]},{"id":176,"t":"welding","pos":"اسم","ar":"لحام (عملية)","ap":"ولدنغ","def":"The process of joining metals by melting.","defAr":"عملية وصل المعادن بالصهر.","ex":"Welding can leave internal defects.","exAr":"اللحام قد يترك عيوبًا داخلية.","src":"التصوير الإشعاعي","lv":"إضافي","c":"c11","l":[]},{"id":177,"t":"pipeline","pos":"اسم","ar":"خط أنابيب","ap":"بايب لاين","def":"Long pipe for oil, gas or water.","defAr":"أنبوب طويل للنفط أو الغاز أو الماء.","ex":"Pipeline welds are radiographed on site.","exAr":"تُصوَّر لحامات الأنابيب في الموقع.","src":"التصوير الإشعاعي","lv":"مهم","c":"c11","l":[]},{"id":178,"t":"pipe","pos":"اسم","ar":"أنبوب","ap":"بايب","def":"A tube carrying fluid.","defAr":"أنبوب لنقل السوائل.","ex":"Place the film around the pipe.","exAr":"ضع الفيلم حول الأنبوب.","src":"التصوير الإشعاعي","lv":"إضافي","c":"c11","l":[]},{"id":179,"t":"defect","pos":"اسم","ar":"عيب","ap":"ديفكت","def":"A flaw that may make a part unacceptable.","defAr":"خلل قد يجعل القطعة غير مقبولة.","ex":"The defect was found in the weld.","exAr":"وُجد العيب في اللحام.","src":"العيوب والجودة","lv":"أساسي","c":"x04","l":[]},{"id":180,"t":"discontinuity","pos":"اسم","ar":"عدم استمرارية (انقطاع في المادة)","ap":"ديسكونتنيويتي","def":"An interruption in the structure of a material.","defAr":"انقطاع في بنية المادة.","ex":"Not every discontinuity is a defect.","exAr":"ليس كل انقطاع عيبًا.","src":"العيوب والجودة","lv":"مهم","c":"x04","l":[]},{"id":181,"t":"crack","pos":"اسم","ar":"شرخ (تشقق)","ap":"كراك","def":"A narrow break in material.","defAr":"كسر ضيق في المادة.","ex":"A crack is a serious defect.","exAr":"الشرخ عيب خطير.","src":"العيوب والجودة","lv":"مهم","c":"x04","l":[]},{"id":182,"t":"porosity","pos":"اسم","ar":"مسامية (فقاعات غاز)","ap":"بوروسيتي","def":"Small gas holes in a weld.","defAr":"ثقوب غازية صغيرة في اللحام.","ex":"Porosity appears as round spots.","exAr":"تظهر المسامية كبقع مستديرة.","src":"العيوب والجودة","lv":"مهم","c":"x04","l":[]},{"id":183,"t":"void","pos":"اسم","ar":"فراغ","ap":"فويد","def":"An empty space inside a material.","defAr":"فراغ داخل مادة.","ex":"A void shows as a dark area.","exAr":"يظهر الفراغ كمنطقة داكنة.","src":"العيوب والجودة","lv":"إضافي","c":"x04","l":[]},{"id":184,"t":"inclusion","pos":"اسم","ar":"شوائب (احتواء)","ap":"إنكلوجن","def":"Foreign material trapped in a weld.","defAr":"مادة غريبة محبوسة في اللحام.","ex":"Slag inclusion is a weld defect.","exAr":"شوائب الخبث عيب لحام.","src":"العيوب والجودة","lv":"إضافي","c":"x04","l":[]},{"id":185,"t":"film","pos":"اسم","ar":"فيلم","ap":"فِلم","def":"Material that records the radiographic image.","defAr":"مادة تسجل الصورة الإشعاعية.","ex":"Develop the film after exposure.","exAr":"اظهر الفيلم بعد التعريض.","src":"الصورة","lv":"أساسي","c":"x04","l":[]},{"id":186,"t":"image","pos":"اسم","ar":"صورة","ap":"إيمدج","def":"The picture produced on film.","defAr":"الصورة الناتجة على الفيلم.","ex":"The image shows the weld.","exAr":"تُظهر الصورة اللحام.","src":"الصورة","lv":"مهم","c":"x04","l":[]},{"id":187,"t":"image quality","pos":"عبارة اصطلاحية","ar":"جودة الصورة","ap":"إيمدج كواليتي","def":"How clearly details show in the image.","defAr":"مدى وضوح التفاصيل في الصورة.","ex":"Image quality depends on energy.","exAr":"جودة الصورة تعتمد على الطاقة.","src":"الصورة","lv":"مهم","c":"x04","l":[]},{"id":188,"t":"sensitivity","pos":"اسم","ar":"حساسية","ap":"سنسيتيفتي","def":"Ability to show small details or detect radiation.","defAr":"القدرة على إظهار تفاصيل صغيرة أو كشف الإشعاع.","ex":"Sensitivity affects defect detection.","exAr":"الحساسية تؤثر في كشف العيوب.","src":"الصورة","lv":"مهم","c":"x04","l":[]},{"id":189,"t":"contrast","pos":"اسم","ar":"تباين","ap":"كونترست","def":"Difference in darkness between areas.","defAr":"فرق الدكنة بين مناطق الصورة.","ex":"Low energy gives higher contrast.","exAr":"الطاقة المنخفضة تعطي تباينًا أعلى.","src":"الصورة","lv":"إضافي","c":"x04","l":[]},{"id":190,"t":"density","pos":"اسم","ar":"كثافة (سواد الفيلم)","ap":"دنسيتي","def":"Blackness of an exposed film.","defAr":"درجة سواد الفيلم المعرّض.","ex":"Film density must be within limits.","exAr":"يجب أن تكون كثافة الفيلم ضمن الحدود.","src":"الصورة","lv":"إضافي","c":"x04","l":[]},{"id":191,"t":"exposure time","pos":"عبارة اصطلاحية","ar":"زمن التعريض","ap":"إكسبوجر تايم","def":"How long the source is out for the image.","defAr":"مدة خروج المصدر لالتقاط الصورة.","ex":"Increase the exposure time for thick steel.","exAr":"زد زمن التعريض للصلب السميك.","src":"الصورة","lv":"أساسي","c":"x04","l":[]},{"id":192,"t":"thickness","pos":"اسم","ar":"سُمك","ap":"ثِكنس","def":"Distance through a material.","defAr":"المسافة عبر المادة.","ex":"Thickness decides the shielding needed.","exAr":"السُّمك يحدد التدريع المطلوب.","src":"الصورة","lv":"أساسي","c":"x04","l":[]},{"id":193,"t":"penetrameter","pos":"اسم","ar":"مؤشر جودة الصورة (بنتراميتر)","ap":"بنتراميتر","def":"A test piece showing image quality.","defAr":"قطعة اختبار تُظهر جودة الصورة.","ex":"Place the penetrameter on the source side.","exAr":"ضع المؤشر على جانب المصدر.","src":"الصورة","lv":"إضافي","c":"x04","l":[]},{"id":194,"t":"geometric unsharpness","pos":"عبارة اصطلاحية","ar":"عدم الحدة الهندسي","ap":"جيومترِك أنشارپنس","def":"Blur caused by source size and distances.","defAr":"ضبابية سببها حجم المصدر والمسافات.","ex":"A small source reduces unsharpness.","exAr":"المصدر الصغير يقلل عدم الحدة.","src":"الصورة","lv":"إضافي","c":"x04","l":[]},{"id":195,"t":"focal spot","pos":"عبارة اصطلاحية","ar":"البقعة البؤرية","ap":"فوكل سبوت","def":"The area on the target where X-rays are made.","defAr":"المنطقة على الهدف التي تنتج منها الأشعة السينية.","ex":"A small focal spot gives a sharper image.","exAr":"البقعة الصغيرة تعطي صورة أحد.","src":"الصورة","lv":"إضافي","c":"c02","l":[]},{"id":196,"t":"source","pos":"اسم","ar":"مصدر","ap":"سورس","def":"The radioactive material or machine producing radiation.","defAr":"المادة المشعة أو الجهاز المنتج للإشعاع.","ex":"Keep the source in its container.","exAr":"أبقِ المصدر في وعائه.","src":"المصادر","lv":"أساسي","c":"c03","l":["tcs85:tcs-4","tcs85:tcs-2","tcs85:tcs-9"]},{"id":197,"t":"sealed source","pos":"عبارة اصطلاحية","ar":"مصدر مختوم","ap":"سيلد سورس","def":"Radioactive material permanently sealed in a capsule.","defAr":"مادة مشعة مغلقة بإحكام داخل كبسولة.","ex":"A sealed source should not leak.","exAr":"المصدر المختوم لا يجب أن يتسرب.","src":"المصادر","lv":"أساسي","c":"c03","l":["tcs85:tcs-2"]},{"id":198,"t":"unsealed source","pos":"عبارة اصطلاحية","ar":"مصدر غير مختوم","ap":"أنسيلد سورس","def":"Radioactive material not sealed in a capsule.","defAr":"مادة مشعة غير محصورة في كبسولة.","ex":"Unsealed sources can contaminate.","exAr":"المصادر غير المختومة قد تلوّث.","src":"المصادر","lv":"إضافي","c":"c03","l":[]},{"id":199,"t":"high-activity source","pos":"عبارة اصطلاحية","ar":"مصدر عالي النشاط","ap":"هاي أكتيفيتي سورس","def":"A source with high activity and serious hazard.","defAr":"مصدر نشاطه عالٍ وخطره كبير.","ex":"Gamma radiography uses high-activity sources.","exAr":"يستخدم تصوير غاما مصادر عالية النشاط.","src":"المصادر","lv":"أساسي","c":"c04","l":[]},{"id":200,"t":"capsule","pos":"اسم","ar":"كبسولة (غلاف المصدر)","ap":"كابسول","def":"The metal case holding the sealed source.","defAr":"الغلاف المعدني الذي يحوي المصدر.","ex":"The source is in a steel capsule.","exAr":"المصدر داخل كبسولة فولاذية.","src":"المصادر","lv":"مهم","c":"c03","l":[]},{"id":201,"t":"cobalt-60","pos":"اسم","ar":"كوبالت-60 (Co-60)","ap":"كوبولت سكستي","def":"A gamma source with half-life about 5.27 years.","defAr":"مصدر غاما نصف عمره نحو 5.27 سنة.","ex":"Co-60 emits two high-energy gamma rays.","exAr":"يصدر Co-60 شعاعي غاما عاليي الطاقة.","src":"المصادر","lv":"أساسي","c":"c03","l":[]},{"id":202,"t":"iridium-192","pos":"اسم","ar":"إيريديوم-192 (Ir-192)","ap":"إيريديوم ناينتي تو","def":"A common gamma source for industrial radiography.","defAr":"مصدر غاما شائع في التصوير الصناعي.","ex":"Ir-192 has a half-life of 74 days.","exAr":"نصف عمر Ir-192 نحو 74 يومًا.","src":"المصادر","lv":"أساسي","c":"c03","l":[]},{"id":203,"t":"selenium-75","pos":"اسم","ar":"سيلينيوم-75 (Se-75)","ap":"سيلينيوم سفنتي فايف","def":"A gamma source used for thinner steel.","defAr":"مصدر غاما للصلب الرقيق.","ex":"Se-75 is used for thin walls.","exAr":"يُستخدم Se-75 للجدران الرقيقة.","src":"المصادر","lv":"مهم","c":"c03","l":[]},{"id":204,"t":"cesium-137","pos":"اسم","ar":"سيزيوم-137 (Cs-137)","ap":"سيزيوم هندرد ثيرتي سفن","def":"A gamma source with half-life about 30 years.","defAr":"مصدر غاما نصف عمره نحو 30 سنة.","ex":"Cs-137 is used in some gauges.","exAr":"يُستخدم Cs-137 في بعض أجهزة القياس.","src":"المصادر","lv":"مهم","c":"c03","l":[]},{"id":205,"t":"americium-241","pos":"اسم","ar":"أمريسيوم-241 (Am-241)","ap":"أمريسيوم تو فورتي وان","def":"A source used in smoke detectors and gauges.","defAr":"مصدر يُستخدم في كواشف الدخان وأجهزة القياس.","ex":"Am-241 emits alpha particles.","exAr":"يصدر Am-241 جسيمات ألفا.","src":"المصادر","lv":"إضافي","c":"c03","l":[]},{"id":206,"t":"exposure device","pos":"عبارة اصطلاحية","ar":"جهاز التعريض (حاوية التصوير)","ap":"إكسبوجر ديفايس","def":"A shielded container that holds and projects the source.","defAr":"حاوية مدرعة تحمل المصدر وتخرجه للتصوير.","ex":"Lock the exposure device after use.","exAr":"اقفل جهاز التعريض بعد الاستخدام.","src":"الأجهزة","lv":"أساسي","c":"c11","l":["tcs85:tcs-4"]},{"id":207,"t":"projector","pos":"اسم","ar":"جهاز إسقاط المصدر (بروجكتور)","ap":"بروجكتر","def":"Another name for a gamma exposure device.","defAr":"اسم آخر لجهاز تعريض أشعة غاما.","ex":"The projector is in its locked position.","exAr":"الجهاز في وضع القفل.","src":"الأجهزة","lv":"إضافي","c":"c11","l":[]},{"id":208,"t":"source changer","pos":"عبارة اصطلاحية","ar":"حاوية تبديل المصدر","ap":"سورس تشينجر","def":"A container used to move sources into or out of devices.","defAr":"حاوية لنقل المصادر داخل الأجهزة أو خارجها.","ex":"Use a source changer to replace the source.","exAr":"استخدم حاوية التبديل لاستبدال المصدر.","src":"الأجهزة","lv":"مهم","c":"c11","l":["tcs85:tcs-4"]},{"id":209,"t":"guide tube","pos":"عبارة اصطلاحية","ar":"أنبوب التوجيه","ap":"غايد تيوب","def":"A flexible tube the source travels through.","defAr":"أنبوب مرن يمر فيه المصدر.","ex":"Check the guide tube for damage.","exAr":"افحص أنبوب التوجيه من التلف.","src":"الأجهزة","lv":"أساسي","c":"c11","l":[]},{"id":210,"t":"drive cable","pos":"عبارة اصطلاحية","ar":"كبل الدفع","ap":"درايف كيبل","def":"A cable that pushes the source out.","defAr":"كبل يدفع المصدر للخارج.","ex":"Inspect the drive cable.","exAr":"افحص كبل الدفع.","src":"الأجهزة","lv":"مهم","c":"c11","l":[]},{"id":211,"t":"pigtail","pos":"اسم","ar":"ذيل المصدر (تجميعة المصدر)","ap":"بيغتيل","def":"The source assembly attached to the drive cable.","defAr":"تجميعة المصدر المتصلة بكبل الدفع.","ex":"The pigtail holds the capsule.","exAr":"الذيل يحمل الكبسولة.","src":"الأجهزة","lv":"مهم","c":"c11","l":["tcs85:tcs-4"]},{"id":212,"t":"wind-out","pos":"اسم","ar":"إخراج المصدر (بالتدوير)","ap":"ويند أوت","def":"Moving the source out of the device by cranking.","defAr":"إخراج المصدر من الجهاز بتدوير المقبض.","ex":"Wind-out is done from a distance.","exAr":"يتم الإخراج من مسافة.","src":"الأجهزة","lv":"أساسي","c":"c11","l":[]},{"id":213,"t":"crank","pos":"اسم","ar":"مقبض التدوير","ap":"كرانك","def":"The handle used for wind-out.","defAr":"المقبض الذي يُدار لإخراج المصدر.","ex":"Turn the crank to wind out.","exAr":"أدر المقبض لإخراج المصدر.","src":"الأجهزة","lv":"مهم","c":"c11","l":[]},{"id":214,"t":"collimator","pos":"اسم","ar":"مجمّع (موجّه) الحزمة","ap":"كوليميتر","def":"A device that shapes the radiation beam.","defAr":"أداة تحدد شكل حزمة الإشعاع.","ex":"A collimator reduces scatter.","exAr":"المجمّع يقلل الاستطارة.","src":"الأجهزة","lv":"مهم","c":"c11","l":[]},{"id":215,"t":"lock","pos":"اسم / فعل","ar":"قفل / يقفل","ap":"لوك","def":"A device that secures the source.","defAr":"أداة تؤمّن المصدر.","ex":"Lock the exposure device.","exAr":"اقفل جهاز التعريض.","src":"الأجهزة","lv":"أساسي","c":"c11","l":[]},{"id":216,"t":"shutter","pos":"اسم","ar":"مصراع","ap":"شاتر","def":"A door that blocks or opens the beam.","defAr":"باب يغلق أو يفتح الحزمة.","ex":"Close the shutter after use.","exAr":"أغلق المصراع بعد الاستخدام.","src":"الأجهزة","lv":"إضافي","c":"c11","l":[]},{"id":217,"t":"interlock","pos":"اسم","ar":"قفل أمان (متشابك)","ap":"إنترلوك","def":"A safety device that stops exposure when a door opens.","defAr":"أداة أمان توقف التعريض عند فتح الباب.","ex":"The interlock stops the X-ray unit.","exAr":"يوقف قفل الأمان جهاز الأشعة.","src":"الأجهزة","lv":"مهم","c":"c11","l":[]},{"id":218,"t":"enclosure","pos":"اسم","ar":"حجرة التصوير (حيز مغلق)","ap":"إنكلوجر","def":"A shielded room or cabinet for radiography.","defAr":"غرفة أو خزانة مدرعة للتصوير.","ex":"Radiography in an enclosure is safer.","exAr":"التصوير في حجرة مدرعة أكثر أمانًا.","src":"الأجهزة","lv":"مهم","c":"c11","l":[]},{"id":219,"t":"site radiography","pos":"عبارة اصطلاحية","ar":"التصوير الموقعي (الميداني)","ap":"سايت ريديوغرافي","def":"Radiography done outside a shielded facility.","defAr":"تصوير خارج المنشأة المدرعة.","ex":"Site radiography needs controlled areas.","exAr":"التصوير الموقعي يحتاج مناطق مراقبة.","src":"التصوير الإشعاعي","lv":"أساسي","c":"c11","l":[]},{"id":220,"t":"crawler","pos":"اسم","ar":"زاحف (جهاز تصوير داخل الأنابيب)","ap":"كرولر","def":"A machine that moves inside a pipe for X-ray exposure.","defAr":"آلة تتحرك داخل الأنبوب للتصوير.","ex":"A crawler makes a panoramic exposure.","exAr":"الزاحف يلتقط تعريضًا بانوراميًا.","src":"الأجهزة","lv":"إضافي","c":"c11","l":[]},{"id":221,"t":"x-ray tube","pos":"عبارة اصطلاحية","ar":"أنبوب الأشعة السينية","ap":"إكس راي تيوب","def":"A vacuum tube that produces X-rays.","defAr":"أنبوب مفرغ ينتج الأشعة السينية.","ex":"The X-ray tube has a cathode and anode.","exAr":"للأنبوب مهبط ومصعد.","src":"الأجهزة","lv":"أساسي","c":"c02","l":[]},{"id":222,"t":"cathode","pos":"اسم","ar":"مهبط (كاثود)","ap":"كاثود","def":"The negative electrode that emits electrons.","defAr":"القطب السالب الذي يصدر الإلكترونات.","ex":"The cathode heats up.","exAr":"يسخن المهبط.","src":"الأجهزة","lv":"مهم","c":"c02","l":[]},{"id":223,"t":"anode","pos":"اسم","ar":"مصعد (أنود)","ap":"أنود","def":"The positive electrode with the target.","defAr":"القطب الموجب وفيه الهدف.","ex":"The anode is made of tungsten.","exAr":"المصعد مصنوع من التنغستن.","src":"الأجهزة","lv":"مهم","c":"c02","l":[]},{"id":224,"t":"target","pos":"اسم","ar":"هدف (الأنود)","ap":"تارغت","def":"The metal hit by electrons to make X-rays.","defAr":"المعدن الذي تصطدم به الإلكترونات لتنتج السينية.","ex":"Electrons hit the target.","exAr":"تصطدم الإلكترونات بالهدف.","src":"الأجهزة","lv":"مهم","c":"c02","l":[]},{"id":225,"t":"tungsten","pos":"اسم","ar":"تنغستن","ap":"تنغستن","def":"A hard metal used as the target.","defAr":"فلز صلب يُستخدم هدفًا.","ex":"Tungsten has a high melting point.","exAr":"للتنغستن درجة انصهار عالية.","src":"الأجهزة","lv":"إضافي","c":"c02","l":[]},{"id":226,"t":"voltage","pos":"اسم","ar":"جهد كهربائي","ap":"فولتج","def":"Electric potential that drives electrons.","defAr":"الجهد الذي يسرّع الإلكترونات.","ex":"Higher voltage gives higher energy X-rays.","exAr":"الجهد الأعلى يعطي أشعة سينية أعلى طاقة.","src":"الأجهزة","lv":"أساسي","c":"c02","l":[]},{"id":227,"t":"tube current","pos":"عبارة اصطلاحية","ar":"تيار الأنبوب","ap":"تيوب كرنت","def":"The flow of electrons in the tube.","defAr":"تدفق الإلكترونات في الأنبوب.","ex":"Tube current is set in mA.","exAr":"يُضبط التيار بالمللي أمبير.","src":"الأجهزة","lv":"مهم","c":"c02","l":[]},{"id":228,"t":"kilovolt","pos":"اسم","ar":"كيلوفولت (kV)","ap":"كيلو فولت","def":"Unit of tube voltage: 1000 volts.","defAr":"وحدة جهد الأنبوب: 1000 فولت.","ex":"The tube runs at 200 kV.","exAr":"يعمل الأنبوب عند 200 kV.","src":"الوحدات","lv":"أساسي","c":"c02","l":[]},{"id":229,"t":"milliampere","pos":"اسم","ar":"ملي أمبير (mA)","ap":"ميلي أمبير","def":"Unit of tube current: one thousandth of an ampere.","defAr":"وحدة تيار الأنبوب: جزء من ألف من الأمبير.","ex":"Set the tube at 5 mA.","exAr":"اضبط الأنبوب عند 5 mA.","src":"الوحدات","lv":"أساسي","c":"c02","l":[]},{"id":230,"t":"workload","pos":"اسم","ar":"حمل العمل (عبء التشغيل)","ap":"وركلود","def":"Total tube current times operating time per week.","defAr":"مجموع تيار الأنبوب في زمن التشغيل أسبوعيًا.","ex":"Workload is used in shielding calculations.","exAr":"يُستخدم حمل العمل في حسابات التدريع.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":231,"t":"primary beam","pos":"عبارة اصطلاحية","ar":"الحزمة الأولية","ap":"برايمري بيم","def":"Radiation coming directly from the source.","defAr":"إشعاع صادر مباشرة من المصدر.","ex":"Never stand in the primary beam.","exAr":"لا تقف في الحزمة الأولية.","src":"الحماية","lv":"أساسي","c":"c08","l":["tcs85:tcs-2"]},{"id":232,"t":"scattered radiation","pos":"عبارة اصطلاحية","ar":"إشعاع مستطار","ap":"سكاترد ريديايشن","def":"Radiation that changed direction after hitting matter.","defAr":"إشعاع تغير اتجاهه بعد اصطدامه بالمادة.","ex":"Scattered radiation reaches behind walls.","exAr":"الإشعاع المستطار يصل خلف الجدران.","src":"الحماية","lv":"مهم","c":"c08","l":["tcs85:tcs-2"]},{"id":233,"t":"sky-shine","pos":"اسم","ar":"الانعكاس الجوي (سكاي شاين)","ap":"سكاي شاين","def":"Radiation scattered back down by the air above.","defAr":"إشعاع تعكسه طبقة الهواء إلى الأسفل.","ex":"Sky-shine can expose people outside.","exAr":"قد يعرّض الانعكاس الجوي أناسًا خارجًا.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":234,"t":"leakage radiation","pos":"عبارة اصطلاحية","ar":"إشعاع التسرب (من الحاوية)","ap":"ليكج ريديايشن","def":"Radiation passing through the shielded housing.","defAr":"إشعاع يخترق جسم الحاوية المدرعة.","ex":"Leakage radiation must be low.","exAr":"يجب أن يكون إشعاع التسرب منخفضًا.","src":"الحماية","lv":"إضافي","c":"c08","l":[]},{"id":235,"t":"survey meter","pos":"عبارة اصطلاحية","ar":"جهاز مسح إشعاعي","ap":"سيرفي ميتر","def":"A portable instrument that measures dose rate.","defAr":"جهاز محمول يقيس معدل الجرعة.","ex":"Use a survey meter after each exposure.","exAr":"استخدم جهاز المسح بعد كل تعريض.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":["tcs85:tcs-10"]},{"id":236,"t":"radiation survey","pos":"عبارة اصطلاحية","ar":"مسح إشعاعي","ap":"ريديايشن سيرفي","def":"Measuring radiation levels in an area.","defAr":"قياس مستويات الإشعاع في منطقة.","ex":"Do a radiation survey before leaving.","exAr":"أجرِ مسحًا إشعاعيًا قبل المغادرة.","src":"الكشف والقياس","lv":"أساسي","c":"c12","l":[]},{"id":237,"t":"monitor","pos":"اسم / فعل","ar":"جهاز رصد / يراقب","ap":"مونيتر","def":"An instrument or action to measure radiation.","defAr":"جهاز أو إجراء لقياس الإشعاع.","ex":"Monitor the area continuously.","exAr":"راقب المنطقة باستمرار.","src":"الكشف والقياس","lv":"أساسي","c":"c12","l":[]},{"id":238,"t":"monitoring","pos":"اسم","ar":"مراقبة (رصد إشعاعي)","ap":"مونيترنغ","def":"Measuring dose or radiation level.","defAr":"قياس الجرعة أو مستوى الإشعاع.","ex":"Individual monitoring uses a dosimeter.","exAr":"المراقبة الفردية تستخدم مقياس جرعات.","src":"الكشف والقياس","lv":"أساسي","c":"c12","l":[]},{"id":239,"t":"detector","pos":"اسم","ar":"كاشف","ap":"ديتكتر","def":"A device that senses radiation.","defAr":"جهاز يستشعر الإشعاع.","ex":"A detector gives a signal.","exAr":"الكاشف يعطي إشارة.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":[]},{"id":240,"t":"detection","pos":"اسم","ar":"كشف","ap":"ديتكشن","def":"Sensing the presence of radiation.","defAr":"استشعار وجود الإشعاع.","ex":"Detection needs a calibrated instrument.","exAr":"الكشف يحتاج جهازًا معايرًا.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":241,"t":"dosimeter","pos":"اسم","ar":"مقياس جرعات (دوزيميتر)","ap":"دوزيميتر","def":"A device worn to record received dose.","defAr":"جهاز يُلبس لتسجيل الجرعة المستلمة.","ex":"Wear your dosimeter at all times.","exAr":"ارتدِ مقياس الجرعات دائمًا.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":["tcs85:tcs-10"]},{"id":242,"t":"personal dosimeter","pos":"عبارة اصطلاحية","ar":"مقياس جرعات شخصي","ap":"برسنل دوزيميتر","def":"A dosimeter worn by one person.","defAr":"مقياس يرتديه شخص واحد.","ex":"Each radiographer wears a personal dosimeter.","exAr":"يرتدي كل مصور مقياسًا شخصيًا.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":["tcs85:tcs-10"]},{"id":243,"t":"electronic personal dosimeter","pos":"عبارة اصطلاحية","ar":"مقياس جرعات شخصي إلكتروني (EPD)","ap":"إليكترونك برسنل دوزيميتر","def":"A direct-reading dosimeter with an alarm.","defAr":"مقياس يقرأ الجرعة مباشرة وفيه إنذار.","ex":"An EPD shows dose in real time.","exAr":"يُظهر EPD الجرعة لحظيًا.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":["tcs85:tcs-10"]},{"id":244,"t":"direct-reading dosimeter","pos":"عبارة اصطلاحية","ar":"مقياس جرعات مباشر القراءة","ap":"دايركت ريدنغ دوزيميتر","def":"A dosimeter you can read at any time.","defAr":"مقياس يمكن قراءته في أي وقت.","ex":"A direct-reading dosimeter shows the dose now.","exAr":"يُظهر المقياس الجرعة الآن.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":245,"t":"thermoluminescent dosimeter","pos":"عبارة اصطلاحية","ar":"مقياس جرعات حراري ضوئي (TLD)","ap":"ثيرمو لومينيسنت دوزيميتر","def":"A dosimeter that stores dose and gives light when heated.","defAr":"مقياس يخزن الجرعة ويصدر ضوءًا عند التسخين.","ex":"A TLD is read in a laboratory.","exAr":"يُقرأ TLD في المختبر.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":["tcs85:tcs-10"]},{"id":246,"t":"film badge","pos":"عبارة اصطلاحية","ar":"شارة الفيلم","ap":"فِلم بادج","def":"A badge using photographic film to record dose.","defAr":"شارة تستخدم فيلمًا لتسجيل الجرعة.","ex":"A film badge is developed monthly.","exAr":"تُظهَّر شارة الفيلم شهريًا.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":247,"t":"pocket dosimeter","pos":"عبارة اصطلاحية","ar":"مقياس جرعات جيبي","ap":"بوكِت دوزيميتر","def":"A small pen-shaped direct-reading dosimeter.","defAr":"مقياس صغير على شكل قلم يقرأ مباشرة.","ex":"Read the pocket dosimeter before and after work.","exAr":"اقرأ المقياس الجيبي قبل العمل وبعده.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":248,"t":"ionization chamber","pos":"عبارة اصطلاحية","ar":"غرفة تأين","ap":"آيونايزيشن تشيمبر","def":"A gas-filled detector that collects ions.","defAr":"كاشف مملوء بالغاز يجمع الأيونات.","ex":"An ionization chamber is accurate for high dose rates.","exAr":"غرفة التأين دقيقة للمعدلات العالية.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":[]},{"id":249,"t":"geiger-müller counter","pos":"عبارة اصطلاحية","ar":"عداد غايغر-مولر (GM)","ap":"غايغر ميلر كاونتر","def":"A gas-filled detector that counts radiation pulses.","defAr":"كاشف غازي يعدّ نبضات الإشعاع.","ex":"A GM counter is sensitive but can saturate.","exAr":"عداد GM حساس لكنه قد يشبع.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":[]},{"id":250,"t":"scintillation detector","pos":"عبارة اصطلاحية","ar":"كاشف وميضي","ap":"سنتيليشن ديتكتر","def":"A detector that flashes light when radiation hits it.","defAr":"كاشف يصدر وميضًا عند ضرب الإشعاع.","ex":"A scintillation detector uses NaI crystal.","exAr":"يستخدم الكاشف الوميضي بلورة NaI.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":251,"t":"sodium iodide","pos":"عبارة اصطلاحية","ar":"يوديد الصوديوم (NaI)","ap":"صوديوم آيودايد","def":"A crystal used in scintillation detectors.","defAr":"بلورة تُستخدم في الكواشف الوميضية.","ex":"NaI(Tl) detects gamma rays well.","exAr":"NaI(Tl) يكشف غاما جيدًا.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":252,"t":"germanium","pos":"اسم","ar":"جرمانيوم","ap":"جيرمينيوم","def":"A semiconductor used in high-resolution detectors.","defAr":"شبه موصل في الكواشف عالية الدقة.","ex":"Germanium detectors have high resolution.","exAr":"كواشف الجرمانيوم عالية الدقة.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":253,"t":"photomultiplier","pos":"اسم","ar":"مضاعف ضوئي","ap":"فوتومالتيبلاير","def":"A tube that amplifies weak light signals.","defAr":"أنبوب يضخّم الإشارات الضوئية الضعيفة.","ex":"A photomultiplier follows the crystal.","exAr":"يأتي المضاعف الضوئي بعد البلورة.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":254,"t":"proportional counter","pos":"عبارة اصطلاحية","ar":"عداد تناسبي","ap":"بروبورشنل كاونتر","def":"A gas detector whose pulse size depends on energy.","defAr":"كاشف غازي يتناسب حجم نبضته مع الطاقة.","ex":"A proportional counter detects alpha and beta.","exAr":"يكشف العداد التناسبي ألفا وبيتا.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":255,"t":"counts per minute","pos":"عبارة اصطلاحية","ar":"عدّات في الدقيقة (cpm)","ap":"كاونتس بير مينت","def":"The number of detected pulses each minute.","defAr":"عدد النبضات المكتشفة كل دقيقة.","ex":"The reading is 500 counts per minute.","exAr":"القراءة 500 عدّة في الدقيقة.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":256,"t":"efficiency","pos":"اسم","ar":"كفاءة","ap":"إفشنسي","def":"The fraction of radiation a detector counts.","defAr":"نسبة ما يعده الكاشف من الإشعاع.","ex":"Detector efficiency varies with energy.","exAr":"تتغير كفاءة الكاشف مع الطاقة.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":257,"t":"calibration","pos":"اسم","ar":"معايرة","ap":"كاليبريشن","def":"Comparing an instrument with a standard.","defAr":"مقارنة الجهاز بمعيار قياسي.","ex":"Calibration is needed every year.","exAr":"المعايرة مطلوبة سنويًا.","src":"الكشف والقياس","lv":"أساسي","c":"c07","l":["tcs85:tcs-10"]},{"id":258,"t":"calibrate","pos":"فعل","ar":"يعاير","ap":"كاليبريت","def":"To adjust and check an instrument against a standard.","defAr":"ضبط الجهاز والتحقق منه بمعيار.","ex":"Calibrate the survey meter yearly.","exAr":"عاير جهاز المسح سنويًا.","src":"الكشف والقياس","lv":"مهم","c":"c07","l":[]},{"id":259,"t":"response","pos":"اسم","ar":"استجابة","ap":"رسبونس","def":"How an instrument reacts to radiation.","defAr":"كيفية تفاعل الجهاز مع الإشعاع.","ex":"Check the instrument response.","exAr":"افحص استجابة الجهاز.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":260,"t":"resolution","pos":"اسم","ar":"دقة التمييز (الفصل)","ap":"ريزوليوشن","def":"The ability to separate close energies or details.","defAr":"القدرة على التمييز بين طاقات أو تفاصيل متقاربة.","ex":"Germanium has better resolution.","exAr":"الجرمانيوم أفضل دقة.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":261,"t":"saturation","pos":"اسم","ar":"تشبّع","ap":"ساتشوريشن","def":"When a detector stops responding at high rates.","defAr":"توقف الكاشف عن الاستجابة عند المعدلات العالية.","ex":"A GM tube can saturate in a high field.","exAr":"قد يتشبع عداد GM في مجال عالٍ.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":262,"t":"dead time","pos":"عبارة اصطلاحية","ar":"زمن ميت","ap":"ديد تايم","def":"Time a detector cannot count after a pulse.","defAr":"زمن لا يستطيع الكاشف العد فيه بعد نبضة.","ex":"Dead time causes undercounting.","exAr":"الزمن الميت يسبب نقصًا في العد.","src":"الكشف والقياس","lv":"إضافي","c":"c07","l":[]},{"id":263,"t":"radiation protection officer","pos":"عبارة اصطلاحية","ar":"مسؤول الحماية من الإشعاع (RPO)","ap":"ريديايشن بروتكشن أوفسر","def":"The person responsible for radiation protection of a licensee.","defAr":"الشخص المسؤول عن الحماية من الإشعاع لدى المرخص له.","ex":"The RPO supervises radiographers.","exAr":"يشرف مسؤول الحماية على المصورين.","src":"اللوائح","lv":"أساسي","c":"c14","l":["tcs85:tcs-1"]},{"id":264,"t":"radiation safety officer","pos":"عبارة اصطلاحية","ar":"مسؤول السلامة الإشعاعية (RSO)","ap":"ريديايشن سيفتي أوفسر","def":"Another name for a radiation protection officer.","defAr":"اسم آخر لمسؤول الحماية.","ex":"The RSO keeps the records.","exAr":"يحفظ المسؤول السجلات.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":265,"t":"licensee","pos":"اسم","ar":"المرخَّص له","ap":"لايسنسي","def":"The person or company holding an authorization.","defAr":"الشخص أو الشركة الحاصلة على ترخيص.","ex":"The licensee is responsible for safety.","exAr":"المرخص له مسؤول عن السلامة.","src":"اللوائح","lv":"أساسي","c":"c14","l":[]},{"id":266,"t":"license","pos":"اسم","ar":"ترخيص","ap":"لايسنس","def":"Official permission to use radiation sources.","defAr":"إذن رسمي لاستخدام مصادر الإشعاع.","ex":"Apply for a license first.","exAr":"قدّم على الترخيص أولًا.","src":"اللوائح","lv":"أساسي","c":"c14","l":["nrrc:nrrc-1"]},{"id":267,"t":"authorization","pos":"اسم","ar":"تصريح (تفويض)","ap":"أوثرايزيشن","def":"Permission granted by the regulator.","defAr":"إذن تمنحه الجهة الرقابية.","ex":"Authorization may be a license or registration.","exAr":"قد يكون التصريح ترخيصًا أو تسجيلًا.","src":"اللوائح","lv":"أساسي","c":"c14","l":["nrrc:nrrc-1"]},{"id":268,"t":"authorized","pos":"صفة","ar":"مصرّح له","ap":"أوثرايزد","def":"Having permission from the regulator.","defAr":"حاصل على إذن من الجهة الرقابية.","ex":"Only authorized persons may enter.","exAr":"المصرح لهم فقط يدخلون.","src":"اللوائح","lv":"أساسي","c":"c14","l":["tcs85:tcs-9","tcs85:tcs-1"]},{"id":269,"t":"registration","pos":"اسم","ar":"تسجيل","ap":"ريجستريشن","def":"Authorization for lower-risk practices.","defAr":"تصريح للممارسات الأقل خطرًا.","ex":"Registration is simpler than a license.","exAr":"التسجيل أبسط من الترخيص.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":270,"t":"notification","pos":"اسم","ar":"إشعار (إخطار)","ap":"نوتفيكيشن","def":"Informing the regulator about a practice.","defAr":"إبلاغ الجهة الرقابية بممارسة.","ex":"Notification is the lowest level.","exAr":"الإخطار أدنى مستوى.","src":"اللوائح","lv":"مهم","c":"c14","l":["nrrc:nrrc-1"]},{"id":271,"t":"permit","pos":"اسم","ar":"تصريح (إذن)","ap":"بيرميت","def":"Written permission to do something.","defAr":"إذن مكتوب للقيام بعمل.","ex":"A permit is needed for transport.","exAr":"يلزم تصريح للنقل.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":272,"t":"regulator","pos":"اسم","ar":"جهة رقابية","ap":"ريغيوليتر","def":"The authority that makes and enforces rules.","defAr":"الجهة التي تضع الأنظمة وتنفذها.","ex":"NRRC is the regulator in Saudi Arabia.","exAr":"NRRC هي الجهة الرقابية في السعودية.","src":"اللوائح","lv":"أساسي","c":"c14","l":["tcs85:tcs-8"]},{"id":273,"t":"regulatory body","pos":"عبارة اصطلاحية","ar":"هيئة رقابية","ap":"ريغيولاتوري بودي","def":"A national authority for safety regulation.","defAr":"سلطة وطنية لتنظيم السلامة.","ex":"The regulatory body inspects licensees.","exAr":"تفتش الهيئة الرقابية المرخص لهم.","src":"اللوائح","lv":"أساسي","c":"c14","l":["tcs85:tcs-8"]},{"id":274,"t":"regulation","pos":"اسم","ar":"لائحة (تنظيم)","ap":"ريغيوليشن","def":"A rule made by an authority.","defAr":"قاعدة تضعها سلطة.","ex":"Follow the regulation.","exAr":"اتبع اللائحة.","src":"اللوائح","lv":"أساسي","c":"c14","l":["nrrc:nrrc-1"]},{"id":275,"t":"compliance","pos":"اسم","ar":"امتثال","ap":"كمبلايانس","def":"Following the rules.","defAr":"الالتزام بالقواعد.","ex":"Compliance is checked by inspection.","exAr":"يُتحقق من الامتثال بالتفتيش.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":276,"t":"inspection","pos":"اسم","ar":"تفتيش (فحص)","ap":"إنسبكشن","def":"An official check of a site or equipment.","defAr":"فحص رسمي لموقع أو معدات.","ex":"The regulator did an inspection.","exAr":"أجرت الجهة الرقابية تفتيشًا.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":277,"t":"safety culture","pos":"عبارة اصطلاحية","ar":"ثقافة السلامة","ap":"سيفتي كلتشر","def":"A shared attitude that puts safety first.","defAr":"اتجاه مشترك يضع السلامة أولًا.","ex":"A strong safety culture prevents accidents.","exAr":"ثقافة السلامة القوية تمنع الحوادث.","src":"اللوائح","lv":"مهم","c":"c14","l":["tcs85:tcs-1"]},{"id":278,"t":"safety assessment","pos":"عبارة اصطلاحية","ar":"تقييم السلامة","ap":"سيفتي أسسمنت","def":"A study of hazards and protection measures.","defAr":"دراسة للمخاطر وإجراءات الحماية.","ex":"Do a safety assessment before work.","exAr":"أجرِ تقييم السلامة قبل العمل.","src":"اللوائح","lv":"مهم","c":"c14","l":["tcs85:tcs-9","ssg11:ssg-3"]},{"id":279,"t":"radiation protection programme","pos":"عبارة اصطلاحية","ar":"برنامج الحماية من الإشعاع (RPP)","ap":"ريديايشن بروتكشن بروغرام","def":"Planned arrangements for protection and safety.","defAr":"ترتيبات مخططة للحماية والسلامة.","ex":"The RPP includes monitoring and training.","exAr":"يشمل البرنامج المراقبة والتدريب.","src":"اللوائح","lv":"أساسي","c":"c14","l":["tcs85:tcs-10"]},{"id":280,"t":"local rules","pos":"عبارة اصطلاحية","ar":"التعليمات المحلية","ap":"لوكل رولز","def":"Written work instructions for a specific site.","defAr":"تعليمات عمل مكتوبة لموقع محدد.","ex":"Read the local rules before work.","exAr":"اقرأ التعليمات المحلية قبل العمل.","src":"اللوائح","lv":"مهم","c":"c14","l":["tcs85:tcs-10"]},{"id":281,"t":"competence","pos":"اسم","ar":"كفاءة (أهلية)","ap":"كومبتنس","def":"Having the knowledge and skill for the job.","defAr":"امتلاك المعرفة والمهارة للمهمة.","ex":"Competence is shown by certification.","exAr":"تثبت الشهادة الكفاءة.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":282,"t":"certificate","pos":"اسم","ar":"شهادة","ap":"سرتفكت","def":"A document proving training or qualification.","defAr":"وثيقة تثبت تدريبًا أو مؤهلًا.","ex":"The radiographer holds a certificate.","exAr":"يحمل المصور شهادة.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":283,"t":"training","pos":"اسم","ar":"تدريب","ap":"تريننغ","def":"Teaching skills and knowledge.","defAr":"تعليم المهارات والمعرفة.","ex":"Training is required for radiographers.","exAr":"التدريب مطلوب للمصورين.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":284,"t":"record","pos":"اسم / فعل","ar":"سجل / يسجل","ap":"ريكورد","def":"Written information that must be kept.","defAr":"معلومات مكتوبة يجب حفظها.","ex":"Keep dose records.","exAr":"احتفظ بسجلات الجرعات.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":285,"t":"inventory","pos":"اسم","ar":"جرد (قائمة المصادر)","ap":"إنفنتري","def":"A list of all sources held.","defAr":"قائمة بكل المصادر المحتفظ بها.","ex":"Update the source inventory.","exAr":"حدّث جرد المصادر.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":286,"t":"security","pos":"اسم","ar":"أمن (حماية من السرقة)","ap":"سيكيورتي","def":"Preventing theft, loss or sabotage.","defAr":"منع السرقة والفقد والتخريب.","ex":"Source security prevents theft.","exAr":"أمن المصدر يمنع السرقة.","src":"اللوائح","lv":"أساسي","c":"c14","l":["tcs85:tcs-9"]},{"id":287,"t":"sabotage","pos":"اسم","ar":"تخريب","ap":"سابوتاج","def":"Deliberate damage to harm or disrupt.","defAr":"إضرار متعمد.","ex":"Protect sources from sabotage.","exAr":"احمِ المصادر من التخريب.","src":"اللوائح","lv":"إضافي","c":"c14","l":[]},{"id":288,"t":"unauthorized","pos":"صفة","ar":"غير مصرح به","ap":"أنأوثرايزد","def":"Without permission.","defAr":"دون إذن.","ex":"Prevent unauthorized access.","exAr":"امنع الدخول غير المصرح به.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":289,"t":"tamper-evident","pos":"صفة","ar":"يُظهر العبث (ختم)","ap":"تامبر إيفيدنت","def":"Showing signs if someone opened it.","defAr":"يُظهر علامات إذا فُتح.","ex":"Use tamper-evident seals.","exAr":"استخدم أختامًا تُظهر العبث.","src":"اللوائح","lv":"إضافي","c":"c14","l":[]},{"id":290,"t":"storage","pos":"اسم","ar":"تخزين","ap":"ستوريج","def":"Keeping sources safely when not used.","defAr":"حفظ المصادر بأمان عند عدم الاستخدام.","ex":"Store sources in a locked place.","exAr":"خزّن المصادر في مكان مقفل.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":291,"t":"disposal","pos":"اسم","ar":"التخلص (الأمن)","ap":"ديسبوزل","def":"Final safe handling of unwanted material.","defAr":"المعالجة النهائية الآمنة للمواد غير المطلوبة.","ex":"Disposal needs regulator approval.","exAr":"التخلص يحتاج موافقة الجهة الرقابية.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":292,"t":"radioactive waste","pos":"عبارة اصطلاحية","ar":"نفايات مشعة","ap":"ريديو أكتف ويست","def":"Unwanted radioactive material.","defAr":"مواد مشعة غير مرغوبة.","ex":"Radioactive waste must be controlled.","exAr":"يجب التحكم بالنفايات المشعة.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":293,"t":"disused source","pos":"عبارة اصطلاحية","ar":"مصدر خارج الخدمة","ap":"ديسيوزد سورس","def":"A source no longer in use.","defAr":"مصدر لم يعد يُستخدم.","ex":"Return the disused source to the supplier.","exAr":"أعد المصدر المنتهي للمورد.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":294,"t":"supplier","pos":"اسم","ar":"مورِّد","ap":"سبلايير","def":"The company that supplies sources.","defAr":"الشركة التي تورّد المصادر.","ex":"Return the source to the supplier.","exAr":"أعد المصدر إلى المورد.","src":"اللوائح","lv":"مهم","c":"c14","l":[]},{"id":295,"t":"transport","pos":"اسم / فعل","ar":"نقل","ap":"ترانسبورت","def":"Moving radioactive material from place to place.","defAr":"نقل مادة مشعة من مكان لآخر.","ex":"Transport follows strict rules.","exAr":"النقل يتبع قواعد صارمة.","src":"النقل","lv":"أساسي","c":"x03","l":["tcs85:tcs-11","nrrc:nrrc-1"]},{"id":296,"t":"package","pos":"اسم","ar":"طرد (عبوة)","ap":"باكج","def":"Packaging with its radioactive contents.","defAr":"العبوة مع محتواها المشع.","ex":"Check the package label.","exAr":"افحص ملصق الطرد.","src":"النقل","lv":"أساسي","c":"x03","l":[]},{"id":297,"t":"packaging","pos":"اسم","ar":"تغليف (مواد التعبئة)","ap":"باكجنغ","def":"The container that holds the contents.","defAr":"الوعاء الذي يحوي المحتوى.","ex":"Packaging must resist accidents.","exAr":"يجب أن يتحمل التغليف الحوادث.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":298,"t":"consignor","pos":"اسم","ar":"المرسِل","ap":"كونسايْنر","def":"The person who sends the package.","defAr":"الشخص الذي يرسل الطرد.","ex":"The consignor prepares the documents.","exAr":"يجهز المرسل المستندات.","src":"النقل","lv":"مهم","c":"x03","l":["tcs85:tcs-11"]},{"id":299,"t":"consignee","pos":"اسم","ar":"المرسَل إليه","ap":"كونسايْني","def":"The person who receives the package.","defAr":"الشخص الذي يستلم الطرد.","ex":"The consignee gets the package.","exAr":"يستلم المرسل إليه الطرد.","src":"النقل","lv":"مهم","c":"x03","l":["tcs85:tcs-11"]},{"id":300,"t":"carrier","pos":"اسم","ar":"الناقل","ap":"كاريير","def":"The company or driver that moves the package.","defAr":"الشركة أو السائق الذي ينقل الطرد.","ex":"The carrier must carry the documents.","exAr":"على الناقل حمل المستندات.","src":"النقل","lv":"مهم","c":"x03","l":["tcs85:tcs-11"]},{"id":301,"t":"driver","pos":"اسم","ar":"سائق","ap":"درايفر","def":"The person driving the vehicle.","defAr":"الشخص الذي يقود المركبة.","ex":"The driver is trained for transport.","exAr":"السائق مدرب على النقل.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":302,"t":"vehicle","pos":"اسم","ar":"مركبة","ap":"فيهِكل","def":"A car or truck carrying packages.","defAr":"سيارة أو شاحنة تحمل الطرود.","ex":"Place a placard on the vehicle.","exAr":"ضع لوحة تحذير على المركبة.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":303,"t":"label","pos":"اسم / فعل","ar":"ملصق / يلصق ملصقًا","ap":"ليبل","def":"A tag on a package showing hazard information.","defAr":"بطاقة على الطرد تبين معلومات الخطر.","ex":"Put the label on two opposite sides.","exAr":"ضع الملصق على جانبين متقابلين.","src":"النقل","lv":"أساسي","c":"x03","l":[]},{"id":304,"t":"placard","pos":"اسم","ar":"لوحة تحذير على المركبة","ap":"بلاكارد","def":"A warning sign on a vehicle.","defAr":"لافتة تحذير على المركبة.","ex":"Display placards on all four sides.","exAr":"اعرض اللوحات على الجوانب الأربعة.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":305,"t":"transport index","pos":"عبارة اصطلاحية","ar":"دليل النقل (TI)","ap":"ترانسبورت إندكس","def":"Maximum dose rate at 1 m from the package in mSv/h × 100.","defAr":"أقصى معدل جرعة على بُعد 1 م من الطرد بوحدة mSv/h مضروبًا في 100.","ex":"The transport index is shown on the label.","exAr":"يظهر دليل النقل على الملصق.","src":"النقل","lv":"أساسي","c":"x03","l":["tcs85:tcs-11"]},{"id":306,"t":"excepted package","pos":"عبارة اصطلاحية","ar":"طرد مستثنى","ap":"إكسبتد باكج","def":"A package with very small activity and few requirements.","defAr":"طرد نشاطه صغير جدًا بمتطلبات قليلة.","ex":"An excepted package has little hazard.","exAr":"الطرد المستثنى قليل الخطر.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":307,"t":"industrial package","pos":"عبارة اصطلاحية","ar":"طرد صناعي","ap":"إندستريال باكج","def":"A package for low-activity material (IP-1 to IP-3).","defAr":"طرد لمواد منخفضة النشاط.","ex":"Industrial packages have three types.","exAr":"للطرود الصناعية ثلاثة أنواع.","src":"النقل","lv":"إضافي","c":"x03","l":[]},{"id":308,"t":"type a package","pos":"عبارة اصطلاحية","ar":"طرد من النوع A","ap":"تايب إي باكج","def":"A package for moderate activity.","defAr":"طرد لنشاط متوسط.","ex":"Type A packages withstand normal transport.","exAr":"طرد A يتحمل النقل العادي.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":309,"t":"type b package","pos":"عبارة اصطلاحية","ar":"طرد من النوع B","ap":"تايب بي باكج","def":"A package for high activity that survives severe accidents.","defAr":"طرد للنشاط العالي يتحمل الحوادث الشديدة.","ex":"Radiography sources travel in Type B packages.","exAr":"تُنقل مصادر التصوير في طرود B.","src":"النقل","lv":"أساسي","c":"x03","l":[]},{"id":310,"t":"exclusive use","pos":"عبارة اصطلاحية","ar":"الاستخدام الحصري (للنقل)","ap":"إكسكلوسف يوز","def":"The consignor uses the whole vehicle alone.","defAr":"يستخدم المرسل المركبة وحده.","ex":"Exclusive use allows higher limits.","exAr":"الاستخدام الحصري يتيح حدودًا أعلى.","src":"النقل","lv":"إضافي","c":"x03","l":["tcs85:tcs-11"]},{"id":311,"t":"category i-white","pos":"عبارة اصطلاحية","ar":"فئة I-أبيض","ap":"كاتيغوري وان وايت","def":"Lowest transport label: very low dose rate on the surface.","defAr":"أدنى ملصق نقل: معدل جرعة سطحي منخفض جدًا.","ex":"I-White has surface dose rate ≤ 0.005 mSv/h.","exAr":"معدل الجرعة السطحي ≤ 0.005 mSv/h.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":312,"t":"category ii-yellow","pos":"عبارة اصطلاحية","ar":"فئة II-أصفر","ap":"كاتيغوري تو يلو","def":"Middle transport label.","defAr":"ملصق النقل المتوسط.","ex":"II-Yellow is for medium dose rates.","exAr":"الفئة II-أصفر لمعدلات متوسطة.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":313,"t":"category iii-yellow","pos":"عبارة اصطلاحية","ar":"فئة III-أصفر","ap":"كاتيغوري ثري يلو","def":"Highest regular transport label.","defAr":"أعلى ملصق نقل عادي.","ex":"III-Yellow has the highest dose rate.","exAr":"III-أصفر أعلى معدل جرعة.","src":"النقل","lv":"مهم","c":"x03","l":[]},{"id":314,"t":"nrrc","pos":"اختصار","ar":"هيئة الرقابة النووية والإشعاعية (السعودية)","ap":"إن آر آر سي","def":"Nuclear and Radiological Regulatory Commission of Saudi Arabia.","defAr":"هيئة الرقابة النووية والإشعاعية في المملكة.","ex":"NRRC regulates radiation sources.","exAr":"تنظم NRRC مصادر الإشعاع.","src":"اللوائح","lv":"أساسي","c":"c14","l":["nrrc:nrrc-1","nrrc:nrrc-5","nrrc:nrrc-2"]},{"id":315,"t":"iaea","pos":"اختصار","ar":"الوكالة الدولية للطاقة الذرية","ap":"آي إي إي إي","def":"International Atomic Energy Agency.","defAr":"الوكالة الدولية للطاقة الذرية.","ex":"The IAEA publishes safety guides.","exAr":"تنشر الوكالة أدلة السلامة.","src":"اللوائح","lv":"أساسي","c":"c14","l":["tcs85:tcs-8","ssg11:ssg-12","tcs85:tcs-11"]},{"id":316,"t":"icrp","pos":"اختصار","ar":"اللجنة الدولية للوقاية من الإشعاع","ap":"آي سي آر بي","def":"International Commission on Radiological Protection.","defAr":"اللجنة الدولية للوقاية الإشعاعية.","ex":"ICRP gives dose recommendations.","exAr":"تقدم ICRP توصيات الجرعات.","src":"اللوائح","lv":"مهم","c":"c14","l":["tcs85:tcs-8","tcs85:tcs-3","tcs85:tcs-5"]}];
const VOCAB_BY_TOPIC = (function () {
  const m = {};
  VOCAB_TERMS.forEach((v) => (v.l || []).forEach((k) => { (m[k] = m[k] || []).push(v.id); }));
  return m;
})();
